	internal class FormMover
	{
		private Point mPoint = new Point(0, 0);

		private bool mouseDown;

		private List<Form> forms = new List<Form>();

		public void AddForm(Form form)
		{
			form.MouseDown += Form_MouseDown;
			form.MouseUp += Form_MouseUp;
			form.MouseMove += Form_MouseMove;
			forms.Add(form);
		}

		public void AddControl(Control control)
		{
			control.MouseDown += Form_MouseDown;
			control.MouseUp += Form_MouseUp;
			control.MouseMove += Form_MouseMove;
		}

		private void Form_MouseDown(object sender, MouseEventArgs e)
		{
			mouseDown = true;
			mPoint = new Point(e.X, e.Y);
		}

		private void Form_MouseUp(object sender, MouseEventArgs e)
		{
			mouseDown = false;
		}

		private void Form_MouseMove(object sender, MouseEventArgs e)
		{
			if (e.Button == MouseButtons.Left && mouseDown)
			{
				_ = mPoint;
				for (int i = 0; i < forms.Count; i++)
				{
					forms[i].Location = new Point(forms[i].Location.X + e.X - mPoint.X, forms[i].Location.Y + e.Y - mPoint.Y);
				}
			}
		}
	}
	public static class GraphicsHelper
	{
		public enum RoundStyle
		{
			None = 0,
			TopLeft = 1,
			TopRight = 2,
			BottomLeft = 4,
			BottomRight = 8,
			Top = 3,
			Bottom = 12,
			All = 15
		}

		public static void SetGDIHigh(this Graphics g)
		{
			g.SmoothingMode = SmoothingMode.AntiAlias;
			g.InterpolationMode = InterpolationMode.HighQualityBicubic;
			g.CompositingQuality = CompositingQuality.HighQuality;
			g.TextRenderingHint = TextRenderingHint.AntiAlias;
		}

		public static Region SetWindowRegion(PaintEventArgs e, int width, int height, int radius, Color borderColor, RoundStyle roundStyle)
		{
			GraphicsPath roundedRectPath = GetRoundedRectPath(new Rectangle(0, 0, width, height), radius, roundStyle);
			Pen pen = new Pen(borderColor, 1f);
			e.Graphics.DrawPath(pen, roundedRectPath);
			return new Region(roundedRectPath);
		}

		public static Region GetWindowRegion(int width, int height, int radius, Color borderColor, RoundStyle roundStyle)
		{
			return new Region(GetRoundedRectPath(new Rectangle(0, 0, width, height), radius, roundStyle));
		}

		public static GraphicsPath GetRoundedRectPath(Rectangle rect, int radius, RoundStyle roundStyle)
		{
			Rectangle rect2 = new Rectangle(rect.Location, new Size(radius, radius));
			GraphicsPath graphicsPath = new GraphicsPath();
			graphicsPath.StartFigure();
			if ((roundStyle & RoundStyle.TopLeft) > RoundStyle.None && radius > 0)
			{
				graphicsPath.AddArc(rect2, 180f, 90f);
			}
			else
			{
				graphicsPath.AddLine(new Point(rect.Left, rect.Top), new Point(rect.Left, rect.Top + radius));
				graphicsPath.AddLine(new Point(rect.Left, rect.Top), new Point(rect.Left + radius, rect.Top));
			}
			rect2.X = rect.Right - radius;
			if ((roundStyle & RoundStyle.TopRight) > RoundStyle.None && radius > 0)
			{
				graphicsPath.AddArc(rect2, 270f, 90f);
			}
			else
			{
				graphicsPath.AddLine(new Point(rect.Right, rect.Top), new Point(rect.Right - radius, rect.Top));
				graphicsPath.AddLine(new Point(rect.Right, rect.Top), new Point(rect.Right, rect.Top + radius));
			}
			rect2.Y = rect.Bottom - radius;
			if ((roundStyle & RoundStyle.BottomRight) > RoundStyle.None && radius > 0)
			{
				graphicsPath.AddArc(rect2, 0f, 90f);
			}
			else
			{
				graphicsPath.AddLine(new Point(rect.Right, rect.Bottom), new Point(rect.Right, rect.Bottom - radius));
				graphicsPath.AddLine(new Point(rect.Right, rect.Bottom), new Point(rect.Right + radius, rect.Bottom));
			}
			rect2.X = rect.Left;
			if ((roundStyle & RoundStyle.BottomLeft) > RoundStyle.None && radius > 0)
			{
				graphicsPath.AddArc(rect2, 90f, 90f);
			}
			else
			{
				graphicsPath.AddLine(new Point(rect.Left, rect.Bottom), new Point(rect.Left - radius, rect.Bottom));
				graphicsPath.AddLine(new Point(rect.Left, rect.Bottom), new Point(rect.Left, rect.Bottom - radius));
			}
			graphicsPath.CloseFigure();
			return graphicsPath;
		}

		public static void FillRect(Graphics g, Rectangle frameRect, int Radius, Color backColor, int frameWidth, Color frameColor, RoundStyle roundStyle)
		{
			g.SetGDIHigh();
			GraphicsPath graphicsPath;
			if (Radius > 0)
			{
				graphicsPath = GetRoundedRectPath(frameRect, Radius, roundStyle);
			}
			else
			{
				graphicsPath = new GraphicsPath();
				graphicsPath.AddRectangle(frameRect);
				graphicsPath.CloseFigure();
			}
			g.FillPath(new SolidBrush(backColor), graphicsPath);
			if (frameWidth > 0)
			{
				Pen pen = new Pen(frameColor, frameWidth);
				g.DrawPath(pen, graphicsPath);
			}
		}

