		public static GraphicsPath GetImageGraphicsPath(Bitmap image, byte alphaFilter)
		{
			int height = image.Height;
			int width = image.Width;
			GraphicsPath graphicsPath = new GraphicsPath();
			for (int i = 0; i < height; i++)
			{
				for (int j = 0; j < width; j++)
				{
					for (; j < width && image.GetPixel(j, i).A < alphaFilter; j++)
					{
					}
					int num = j;
					for (; j < width && image.GetPixel(j, i).A > alphaFilter; j++)
					{
					}
					int num2 = j;
					if (num2 > num)
					{
						graphicsPath.AddRectangle(new Rectangle(num, i, num2 - num, 1));
					}
				}
			}
			return graphicsPath;
		}

		public static Region GetImageRegion(Bitmap bitmap, Size formSize, byte alphaFilter)
		{
			return new Region(GetImageGraphicsPath(bitmap.ScaleToSize(formSize), alphaFilter));
		}

		public static Bitmap ScaleToSize(this Bitmap bitmap, int width, int height)
		{
			if (bitmap.Width == width && bitmap.Height == height)
			{
				return bitmap;
			}
			Bitmap bitmap2 = new Bitmap(width, height);
			using Graphics graphics = Graphics.FromImage(bitmap2);
			graphics.InterpolationMode = InterpolationMode.HighQualityBicubic;
			graphics.DrawImage(bitmap, 0, 0, width, height);
			return bitmap2;
		}

		public static Bitmap ScaleToSize(this Bitmap bitmap, Size size)
		{
			return bitmap.ScaleToSize(size.Width, size.Height);
		}

		public static Bitmap FillBitmapWithColor(Bitmap bitmap, Color srcColor, Color dstColor)
		{
			Bitmap bitmap2 = new Bitmap(bitmap);
			for (int i = 0; i < bitmap.Height; i++)
			{
				for (int j = 0; j < bitmap.Width; j++)
				{
					Color pixel = bitmap.GetPixel(j, i);
					if (pixel == srcColor)
					{
						bitmap2.SetPixel(j, i, dstColor);
					}
					else
					{
						bitmap2.SetPixel(j, i, pixel);
					}
				}
			}
			return bitmap2;
		}

		public static void FillBitmapWithColor(Bitmap bitmap, Rectangle fillRect, Color fillColor)
		{
			Color color = Color.FromArgb(0, 0, 0, 0);
			Rectangle rectangle = Rectangle.Intersect(fillRect, new Rectangle(0, 0, bitmap.Width, bitmap.Height));
			for (int i = rectangle.Y; i < rectangle.Height; i++)
			{
				for (int j = rectangle.X; j < rectangle.Width; j++)
				{
					if (bitmap.GetPixel(j, i) == color)
					{
						bitmap.SetPixel(j, i, fillColor);
					}
				}
			}
		}
	}
	internal class ImageHelper
	{
		public static bool IsRealImage(string path)
		{
			if (path == null || path == "")
			{
				return false;
			}
			try
			{
				Image.FromFile(path).Dispose();
				return true;
			}
			catch
			{
				return false;
			}
		}

		public static Image GetImage(string fileName)
		{
			Image result = null;
			if (File.Exists(fileName) && IsRealImage(fileName))
			{
				FileStream fileStream = new FileStream(fileName, FileMode.Open);
				result = Image.FromStream(fileStream);
				fileStream.Close();
			}
			return result;
		}

		public static byte[] GetBytesFromImagePath(string strFile)
		{
			byte[] result = null;
			if (IsRealImage(strFile))
			{
				using FileStream fileStream = new FileStream(strFile, FileMode.Open, FileAccess.Read);
				using BinaryReader binaryReader = new BinaryReader(fileStream);
				result = binaryReader.ReadBytes((int)fileStream.Length);
			}
			return result;
		}

		public static Image GetImageFromBytes(byte[] bytes)
		{
			Image image = null;
			using MemoryStream memoryStream = new MemoryStream(bytes);
			memoryStream.Write(bytes, 0, bytes.Length);
			return Image.FromStream(memoryStream, useEmbeddedColorManagement: true);
		}

		public static Bitmap ReadImageFile(string path)
		{
			Bitmap result = null;
			try
			{
				FileStream fileStream = File.OpenRead(path);
				int num = 0;
				num = (int)fileStream.Length;
				byte[] buffer = new byte[num];
				fileStream.Read(buffer, 0, num);
				Image original = Image.FromStream(fileStream);
				fileStream.Close();
				result = new Bitmap(original);
			}
			catch
			{
			}
			return result;
		}

		public static Bitmap GetImageWithRect(string fileName, Rectangle rect)
		{
			Bitmap result = null;
			try
			{
				Bitmap bitmap = ReadImageFile(fileName);
				if (bitmap != null)
				{
					int num = 0;
					int num2 = 0;
					int width = bitmap.Width;
					int height = bitmap.Height;
					int width2 = rect.Size.Width;
					int height2 = rect.Size.Height;
					if (height > height2 || width > width2)
					{
						if (width * height2 > height * width2)
						{
							num = width2;
							num2 = width2 * height / width;
						}
						else
						{
							num2 = height2;
							num = width * height2 / height;
						}
					}
					else
					{
						num = width;
						num2 = height;
					}
					result = new Bitmap(bitmap, new Size(num, num2));
					bitmap.Dispose();
				}
			}
			catch
			{
			}
			return result;
		}

		public static Icon GetIcon(string ImageFileName, Size size)
		{
			if (File.Exists(ImageFileName))
			{
				using (Bitmap bitmap = new Bitmap(ImageFileName))
				{
					string text = Path.GetExtension(ImageFileName).ToLower();
					if (bitmap.Width == size.Width && bitmap.Height == size.Height && text.Equals(".ico"))
					{
						using (Bitmap bitmap2 = new Bitmap(bitmap))
						{
							return Icon.FromHandle(bitmap2.GetHicon());
						}
					}
					using Bitmap bitmap3 = new Bitmap(bitmap, size);
					return Icon.FromHandle(bitmap3.GetHicon());
				}
			}
			return null;
		}

		public static byte[] GetIconBytes(string ImageFileName, Size size)
		{
			if (File.Exists(ImageFileName))
			{
				using (Bitmap bitmap = new Bitmap(ImageFileName))
				{
					string text = Path.GetExtension(ImageFileName).ToLower();
					if (bitmap.Width == 32 && bitmap.Height == 32 && text.Equals(".ico"))
					{
						using (MemoryStream memoryStream = new MemoryStream())
						{
							bitmap.Save(memoryStream, ImageFormat.Bmp);
							return memoryStream.GetBuffer();
						}
					}
					using Bitmap bitmap2 = new Bitmap(bitmap, size);
					using MemoryStream memoryStream2 = new MemoryStream();
					bitmap2.Save(memoryStream2, ImageFormat.Bmp);
					return memoryStream2.GetBuffer();
				}
			}
			return null;
		}

		public static Bitmap ImageTailor(Bitmap src, Rectangle rect)
		{
			return src.Clone(rect, PixelFormat.Undefined);
		}
	}
	public class SkinForm : Form
	{
		private FormMover formMover = new FormMover();

		public Form ControlsForm;

		private int formLocationOffset;

		private bool Movable = true;

		private IContainer components;

		protected override CreateParams CreateParams
		{
			get
			{
				CreateParams obj = base.CreateParams;
				obj.ExStyle |= 524288;
				return obj;
			}
		}

		public SkinForm(bool movable)
		{
			InitializeComponent();
			SetStyles();
			Movable = movable;
		}

		public void AddControl(Control control)
		{
			if (Movable)
			{
				formMover.AddControl(control);
			}
		}

		public void InitSkin(Form form, int reduce, int radius)
		{
			if (Movable)
			{
				formMover.AddForm(form);
			}
			ControlsForm = form;
			ControlsForm.Owner = this;
			base.ShowInTaskbar = true;
			ControlsForm.ShowInTaskbar = false;
			base.FormBorderStyle = FormBorderStyle.None;
			BackgroundImageLayout = ImageLayout.Stretch;
			base.Icon = ControlsForm.Icon;
			base.ShowIcon = ControlsForm.ShowIcon;
			Text = ControlsForm.Text;
			Font = ControlsForm.Font;
			base.Size = ControlsForm.BackgroundImage.Size;
			base.StartPosition = FormStartPosition.CenterParent;
			BackgroundImage = new Bitmap(ControlsForm.BackgroundImage, base.Size);
			ControlsForm.Width = base.Size.Width - reduce * 2;
			ControlsForm.Height = base.Size.Height - reduce * 2;
			formLocationOffset = reduce;
			Rectangle rect = new Rectangle(reduce, reduce, ControlsForm.Width, ControlsForm.Height);
			Bitmap backgroundImage = ImageHelper.ImageTailor(new Bitmap(ControlsForm.BackgroundImage), rect);
			ControlsForm.BackgroundImage = backgroundImage;
			ControlsForm.Region = GraphicsHelper.GetWindowRegion(rect.Width, rect.Height, radius, Color.Transparent, GraphicsHelper.RoundStyle.All);
			ControlsForm.FormClosing += Form_FormClosing;
			ControlsForm.LocationChanged += ControlsForm_LocationChanged;
			ControlsForm.Load += ControlsForm_Load;
			foreach (Control control in ControlsForm.Controls)
			{
				control.Location = new Point(control.Location.X - reduce, control.Location.Y - reduce);
			}
			base.Activated += SkinForm_Activated;
		}

		private void SkinForm_Activated(object sender, EventArgs e)
		{
			ControlsForm.Activate();
		}

		private void ControlsForm_Load(object sender, EventArgs e)
		{
			base.Location = new Point(ControlsForm.Location.X - formLocationOffset, ControlsForm.Location.Y - formLocationOffset);
			Show();
		}

		private void ControlsForm_LocationChanged(object sender, EventArgs e)
		{
			base.Location = new Point(ControlsForm.Location.X - formLocationOffset, ControlsForm.Location.Y - formLocationOffset);
		}

		private void Form_FormClosing(object sender, FormClosingEventArgs e)
		{
			ControlsForm.Owner = null;
			Close();
		}

		public void AllHide()
		{
			Hide();
			ControlsForm.Hide();
		}

		public void AllShow()
		{
			Show();
			ControlsForm.Show();
		}

		private void SetStyles()
		{
			SetStyle(ControlStyles.UserPaint | ControlStyles.ResizeRedraw | ControlStyles.AllPaintingInWmPaint | ControlStyles.DoubleBuffer | ControlStyles.OptimizedDoubleBuffer, value: true);
			UpdateStyles();
			base.AutoScaleMode = AutoScaleMode.None;
		}

		public void SetBits()
		{
			if (BackgroundImage == null)
			{
				return;
			}
			Bitmap bitmap = new Bitmap(BackgroundImage, base.Width, base.Height);
			if (!Image.IsCanonicalPixelFormat(bitmap.PixelFormat) || !Image.IsAlphaPixelFormat(bitmap.PixelFormat))
			{
				throw new ApplicationException("图片必须是32位带Alhpa通道的图片。");
			}
			IntPtr hObj = IntPtr.Zero;
			IntPtr dC = Win32.GetDC(IntPtr.Zero);
			IntPtr intPtr = IntPtr.Zero;
			IntPtr intPtr2 = Win32.CreateCompatibleDC(dC);
			try
			{
				Win32.Point pptDst = new Win32.Point(base.Left, base.Top);
				Win32.Size psize = new Win32.Size(base.Width, base.Height);
				Win32.BLENDFUNCTION pblend = default(Win32.BLENDFUNCTION);
				Win32.Point pptSrc = new Win32.Point(0, 0);
				intPtr = bitmap.GetHbitmap(Color.FromArgb(0));
				hObj = Win32.SelectObject(intPtr2, intPtr);
				pblend.BlendOp = 0;
				pblend.SourceConstantAlpha = byte.MaxValue;
				pblend.AlphaFormat = 1;
				pblend.BlendFlags = 0;
				Win32.UpdateLayeredWindow(base.Handle, dC, ref pptDst, ref psize, intPtr2, ref pptSrc, 0, ref pblend, 2);
			}
			finally
			{
				if (intPtr != IntPtr.Zero)
				{
					Win32.SelectObject(intPtr2, hObj);
					Win32.DeleteObject(intPtr);
				}
				Win32.ReleaseDC(IntPtr.Zero, dC);
				Win32.DeleteDC(intPtr2);
			}
		}

		protected override void OnBackgroundImageChanged(EventArgs e)
		{
			base.OnBackgroundImageChanged(e);
			SetBits();
		}

		protected override void OnResize(EventArgs e)
		{
			base.OnResize(e);
			SetBits();
		}

		protected override void Dispose(bool disposing)
		{
			if (disposing && components != null)
			{
				components.Dispose();
			}
			base.Dispose(disposing);
