		public int GetLanguageFileCount()
		{
			LanguageCount = 0;
			string path = Application.StartupPath + "\\Language";
			if (!Directory.Exists(path))
			{
				return LanguageCount;
			}
			FilePaths = Directory.GetFiles(path, "*.xml");
			if (FilePaths.Count() == 0)
			{
				return LanguageCount;
			}
			LanguageType = new string[FilePaths.Count()];
			for (int i = 0; i < FilePaths.Count(); i++)
			{
				XElement root = XDocument.Load(FilePaths[i]).Root;
				LanguageType[LanguageCount] = root.Name.ToString();
				LanguageCount++;
			}
			int index = 0;
			if (RegeditManager.GetLanguageIndex(out index))
			{
				LanguageIndex = index;
			}
			else
			{
				if (LanguageCount > 1)
				{
					LanguageIndex = 1;
				}
				RegeditManager.SaveLanguageIndex(LanguageIndex);
			}
			return LanguageCount;
		}

		public static float GetFontSize(int index)
		{
			float result = 10.5f;
			XmlDocument xmlDocument = new XmlDocument();
			xmlDocument.Load(FilePaths[index]);
			XmlNode xmlNode = xmlDocument.GetElementsByTagName("FontSize")[0];
			if (xmlNode != null)
			{
				result = float.Parse(xmlNode.InnerText, CultureInfo.InvariantCulture);
			}
			return result;
		}

		public static void ForeachSetColor(Control father, DriveConfig.DriveParam driveParam)
		{
			foreach (Control control in father.Controls)
			{
				if (control is CustomTrackBar)
				{
					((CustomTrackBar)control).SliderColor = driveParam.SliderClr;
				}
				if (control is TextBox)
				{
					TextBox textBox = (TextBox)control;
					if (textBox.Name.Contains("Dlg"))
					{
						textBox.BackColor = driveParam.DlgTxtBgClr;
						textBox.ForeColor = driveParam.DlgTxtForeClr;
					}
					else
					{
						textBox.BackColor = driveParam.TxtBgClr;
						textBox.ForeColor = driveParam.TxtForeClr;
					}
				}
				if (control is ListView)
				{
					((ListView)control).BackColor = driveParam.LstViewBgClr;
				}
				if (control is CustomListView)
				{
					((CustomListView)control).BackColor = driveParam.LstViewBgClr;
				}
				if (control is Label)
				{
					((Label)control).ForeColor = driveParam.LblForeClr;
				}
				if (control is CustomButton)
				{
					((CustomButton)control).ForeColor = driveParam.BtnForeClr;
				}
				if (control.HasChildren)
				{
					if (control is CustomComboBox)
					{
						CustomComboBox obj = (CustomComboBox)control;
						Color unselectItemColor = (obj.BackColor = driveParam.CbbBgClr);
						obj.UnselectItemColor = unselectItemColor;
						obj.SelectItemColor = driveParam.CbbItemClr;
						obj.ForeColor = driveParam.CbbForeClr;
						obj.ArrowImageNoraml = ResourcesFile.GetComboxBoxBitmap();
					}
					else
					{
						ForeachSetColor(control, driveParam);
					}
				}
			}
		}

		public static void FormSetColor(Control father)
		{
			Form obj = (Form)father;
			obj.Icon = new Icon(Application.StartupPath + "\\res\\logo.ico");
			obj.Text = DriveConfig.GetDriveName();
			DriveConfig.DriveParam driveParam = DriveConfig.GetDriveParam();
			ForeachSetColor(father, driveParam);
		}

		public void ForeachSetControl(Control father)
		{
			foreach (Control control in father.Controls)
			{
				if (control is Label)
				{
					Label label = (Label)control;
					for (int i = 0; i < LabelStructs.Count; i++)
					{
						if (label.Name == LabelStructs[i].Name)
						{
							label.Text = LabelStructs[i].Text;
							break;
						}
					}
				}
				else if (control is CustomButton)
				{
					CustomButton customButton = (CustomButton)control;
					for (int j = 0; j < LabelStructs.Count; j++)
					{
						if (customButton.Name == LabelStructs[j].Name)
						{
							customButton.Text = LabelStructs[j].Text;
							break;
						}
					}
				}
				else if (control is CustomRecordMacro)
				{
					CustomRecordMacro customRecordMacro = (CustomRecordMacro)control;
					for (int k = 0; k < LabelStructs.Count; k++)
					{
						if (LabelStructs[k].Name == customRecordMacro.Name + "_start")
						{
							customRecordMacro.StartText = LabelStructs[k].Text;
						}
						else if (LabelStructs[k].Name == customRecordMacro.Name + "_stop")
						{
							customRecordMacro.StopText = LabelStructs[k].Text;
						}
					}
				}
				else
				{
					if (!control.HasChildren)
					{
						continue;
					}
					if (control is CustomComboBox)
					{
						CustomComboBox customComboBox = (CustomComboBox)control;
						for (int l = 0; l < ComboBoxStructs.Count; l++)
						{
							if (customComboBox.Name == ComboBoxStructs[l].Name)
							{
								customComboBox.Item.Clear();
								for (int m = 0; m < ComboBoxStructs[l].Items.Count; m++)
								{
									customComboBox.Item.Add(ComboBoxStructs[l].Items[m]);
								}
								customComboBox.SelectIndex = ComboxIndexList[l];
								break;
							}
						}
					}
					else
					{
						ForeachSetControl(control);
					}
				}
			}
		}

		public void ForeachGetControl(Control father)
		{
			foreach (Control control in father.Controls)
			{
				if (control is Label)
				{
					Label label = (Label)control;
					LabelStruct item = new LabelStruct
					{
						Name = label.Name,
						Text = label.Text
					};
					LabelStructs.Add(item);
				}
				else if (control is CustomButton)
				{
					CustomButton customButton = (CustomButton)control;
					if (customButton.Text != "")
					{
						LabelStruct item2 = new LabelStruct
						{
							Name = customButton.Name,
							Text = customButton.Text
						};
						LabelStructs.Add(item2);
					}
				}
				else if (control is CustomRadioButton)
				{
					CustomRadioButton customRadioButton = (CustomRadioButton)control;
					if (customRadioButton.Text != "")
					{
						LabelStruct item3 = new LabelStruct
						{
							Name = customRadioButton.Name,
							Text = customRadioButton.TextString
						};
						LabelStructs.Add(item3);
					}
				}
				else if (control is CustomRecordMacro)
				{
					CustomRecordMacro customRecordMacro = (CustomRecordMacro)control;
					LabelStruct item4 = new LabelStruct
					{
						Name = customRecordMacro.Name + "_start",
						Text = customRecordMacro.StartText
					};
					LabelStructs.Add(item4);
					item4 = new LabelStruct
					{
						Name = customRecordMacro.Name + "_stop",
						Text = customRecordMacro.StopText
					};
					LabelStructs.Add(item4);
				}
				else
				{
					if (!control.HasChildren)
					{
						continue;
					}
					if (control is CustomComboBox)
					{
						CustomComboBox customComboBox = (CustomComboBox)control;
						ComboBoxStruct item5 = default(ComboBoxStruct);
						item5.Name = customComboBox.Name;
						item5.Items = new List<string>();
						item5.Items.Clear();
						for (int i = 0; i < customComboBox.Item.Count; i++)
						{
							item5.Items.Add(customComboBox.Item[i].ToString());
						}
						ComboBoxStructs.Add(item5);
						ComboxIndexList.Add(customComboBox.SelectIndex);
					}
					else
					{
						ForeachGetControl(control);
					}
				}
			}
		}

