		{
			base.OnMouseEnter(e);
			mouseStatus = MouseStatus.Enter;
			Invalidate();
		}

		protected override void OnMouseLeave(EventArgs e)
		{
			base.OnMouseLeave(e);
			mouseStatus = MouseStatus.Leave;
			Invalidate();
		}
