			DrawControl(falg: true);
			AdjustComboBoxLocation();
		}

		private void DrawControl(bool falg)
		{
			SuspendLayout();
			_ComboBox.BackColor = BackColor;
			_ComboBox.Width = base.Width;
			_ComboBox.Font = new Font(Font.Name, Font.Size);
			_ComboBox.ForeColor = ForeColor;
			_ComboBox.Size = base.Size;
			_ComboBox.DropDownStyle = ComboBoxStyle.DropDownList;
			if (falg)
			{
				_ComboBox.SelectedIndexChanged += ComboBox_SelectedIndexChanged;
				_ComboBox.TextChanged += ComboBox_TextChanged;
			}
			_ComboBox.DrawMode = DrawMode.OwnerDrawVariable;
			_ComboBox.DrawItem += ComboBox_DrawItem;
			_Button.Dock = DockStyle.Right;
			_Button.FlatStyle = FlatStyle.Flat;
			_Button.FlatAppearance.BorderSize = 0;
			_Button.FlatAppearance.MouseDownBackColor = BackColor;
			_Button.FlatAppearance.MouseOverBackColor = BackColor;
			_Button.FlatAppearance.CheckedBackColor = BackColor;
			_Button.BackColor = BackColor;
			_Button.Size = new Size(30, 30);
			_Button.Cursor = Cursors.Default;
			if (falg)
			{
				_Button.Click += Icon_Click;
				_Button.Paint += Icon_Paint;
			}
			_Label.Dock = DockStyle.Fill;
			_Label.AutoSize = false;
			_Label.BackColor = BackColor;
			_Label.TextAlign = ContentAlignment.MiddleCenter;
			_Label.Padding = new Padding(8, 0, 0, 0);
			_Label.Font = new Font(Font.Name, Font.Size);
			_Label.ForeColor = ForeColor;
			_Label.Size = new Size(base.Width, base.Height);
			if (falg)
			{
				_Label.Click += Surface_Click;
				_Label.MouseEnter += Surface_MouseEnter;
				_Label.MouseLeave += Surface_MouseLeave;
			}
			base.Controls.Add(_Label);
			base.Controls.Add(_Button);
			base.Controls.Add(_ComboBox);
			base.Size = new Size(base.Width, base.Height);
			ForeColor = ForeColor;
			Font = new Font(Font.Name, Font.Size);
			base.BackColor = BackColor;
			ResumeLayout();
		}

		private void ComboBox_DrawItem(object sender, DrawItemEventArgs e)
		{
			e.DrawBackground();
			e.DrawFocusRectangle();
			if (e.Index >= 0)
			{
				Color color = _UnselectItemColor;
				if ((e.State & DrawItemState.Selected) != DrawItemState.None)
				{
					color = _SelectItemColor;
				}
				Rectangle bounds = e.Bounds;
				SolidBrush brush = new SolidBrush(color);
				Graphics graphics = e.Graphics;
				graphics.DrawRectangle(new Pen(Color.Transparent), bounds);
				graphics.FillRectangle(brush, bounds);
				graphics.DrawString(_ComboBox.Items[e.Index].ToString(), Font, new SolidBrush(ForeColor), bounds.X, bounds.Y);
			}
		}

		private void Icon_Paint(object sender, PaintEventArgs e)
		{
			if (_ArrowImageNoraml != null)
			{
				int num = base.Height - _ArrowImageNoraml.Height;
				Rectangle rect = new Rectangle(e.ClipRectangle.X + _ArrowImageNoraml.Width, num / 2, _ArrowImageNoraml.Width, _ArrowImageNoraml.Height);
				e.Graphics.DrawImage(_ArrowImageNoraml, rect);
			}
		}

		protected override void OnResize(EventArgs e)
		{
			base.OnResize(e);
			DrawControl(falg: false);
			AdjustComboBoxLocation();
		}

		private void ComboBox_SelectedIndexChanged(object sender, EventArgs e)
		{
			if (OnSelectedIndexChanged != null)
			{
				OnSelectedIndexChanged(sender, e);
			}
			_Label.Text = _ComboBox.Text;
		}

		private void ComboBox_TextChanged(object sender, EventArgs e)
		{
			_Label.ForeColor = ForeColor;
			_Label.Text = _ComboBox.Text;
		}

		private void Icon_Click(object sender, EventArgs e)
		{
			_ComboBox.Select();
			_ComboBox.DroppedDown = true;
		}

		private void Surface_Click(object sender, EventArgs e)
		{
			OnClick(e);
			_ComboBox.Select();
			_ComboBox.DroppedDown = true;
		}

		private void Surface_MouseLeave(object sender, EventArgs e)
		{
			OnMouseLeave(e);
		}

		private void Surface_MouseEnter(object sender, EventArgs e)
		{
			OnMouseEnter(e);
		}

		private void AdjustComboBoxLocation()
		{
			if (_ArrowDirection == ArrowDirectionEnum.Down)
			{
				_ComboBox.Location = new Point
				{
					X = 0,
					Y = base.Height - Font.Height - 8
				};
			}
			else
			{
				_ComboBox.Location = new Point
				{
					X = _ComboBox.Width + 1,
					Y = 0
				};
			}
		}
	}
