		public CustomDeviceButton()
		{
			SetStyle(ControlStyles.UserPaint | ControlStyles.ResizeRedraw | ControlStyles.SupportsTransparentBackColor | ControlStyles.AllPaintingInWmPaint | ControlStyles.DoubleBuffer | ControlStyles.OptimizedDoubleBuffer, value: true);
			UpdateStyles();
			base.Appearance = Appearance.Button;
			base.FlatStyle = FlatStyle.Flat;
			base.FlatAppearance.BorderSize = 0;
			base.FlatAppearance.CheckedBackColor = Color.Transparent;
			base.FlatAppearance.MouseOverBackColor = Color.Transparent;
			base.FlatAppearance.MouseDownBackColor = Color.Transparent;
			AutoSize = false;
		}

		protected override void SetBoundsCore(int x, int y, int width, int height, BoundsSpecified specified)
		{
			int val = ((_OnlineImage != null) ? _OnlineImage.Width : 0);
			int val2 = ((_OnlineImage != null) ? _OnlineImage.Height : 0);
			int val3 = ((_OfflineImage != null) ? _OfflineImage.Width : 0);
			int val4 = ((_OfflineImage != null) ? _OfflineImage.Height : 0);
			int num = Math.Max(val, val3);
			num = ((num == 0) ? width : num);
			int num2 = Math.Max(val2, val4);
			num2 = ((num2 == 0) ? height : num2);
			if (_DeviceName != "")
			{
				int num3 = Convert.ToInt32(CreateGraphics().MeasureString(_DeviceName, Font).Height) + 4;
				num2 += num3;
			}
			base.SetBoundsCore(x, y, num, num2, specified);
		}

		protected override void OnPaint(PaintEventArgs e)
		{
			base.OnPaint(e);
			e.Graphics.SmoothingMode = SmoothingMode.HighQuality;
			Image image = null;
			Image image2 = null;
			if (_QuestionImage == null)
			{
				image = ((!_Online) ? _OfflineImage : _OnlineImage);
				image2 = ((!_IsWired) ? _WirelessImage : _WiredImage);
			}
			else if (_Online)
			{
				image = _OnlineImage;
				image2 = ((!_IsWired) ? _WirelessImage : _WiredImage);
			}
			else
			{
				image = _OfflineImage;
				image2 = _QuestionImage;
			}
			if (image == null)
			{
				SolidBrush solidBrush = new SolidBrush(BackColor);
				e.Graphics.FillRectangle(solidBrush, e.ClipRectangle);
				solidBrush.Dispose();
				return;
			}
			Rectangle rect = new Rectangle(0, 0, image.Size.Width, image.Size.Height);
			e.Graphics.DrawImageUnscaledAndClipped(image, rect);
			if (image2 != null && ((_Online && _QuestionImage == null) || _QuestionImage != null))
			{
				imageRect = new Rectangle(base.Width - image2.Width - 25, 20, image2.Width, image2.Height);
				e.Graphics.DrawImageUnscaledAndClipped(image2, imageRect);
			}
			if (_ReportRateImage != null)
			{
				rect = new Rectangle(25, 20, _ReportRateImage.Width, _ReportRateImage.Height);
				e.Graphics.DrawImageUnscaledAndClipped(_ReportRateImage, rect);
			}
		}

		protected override void OnMouseMove(MouseEventArgs mevent)
		{
			base.OnMouseMove(mevent);
			if (_QuestionImage == null)
			{
				return;
			}
			if (!_Online)
			{
				if (imageRect.Contains(mevent.Location))
				{
					QuestionEnter?.Invoke(this);
				}
				else
				{
					QuestionLevae?.Invoke(this);
				}
			}
			else
			{
				QuestionLevae?.Invoke(this);
			}
		}
	}
