	[Category("自定义")]
	[DefaultEvent("CustomScroll")]
	public class CustomScrollBar : Control
	{
		public delegate void CustomScrollEventHandler(object sender, CustomEventArgs e);

		private Color _BarColor = Color.Gray;

		private Color _SliderColor = Color.White;

		private bool _IsRound = true;

		private Orientation _Orientation = Orientation.Vertical;

		private int _BarSize = 10;

		private int _BarRadius = 16;

		private int _Interval = 2;

		private float _PageSize = 1f;

		private float _DocSize = 10f;

		private float _DocPosition;

		private float _ScrollInterval = 10f;

		private float fPageDocRatio;

		private float fShowScrollRatio;

		private float fAbove;

		private float fCapWidth;

		private float fCapHalfWidth;

		private MouseStatus mouseStatus = MouseStatus.Leave;

		[Category("自定义")]
		[Description("背景条颜色")]
		public Color BarColor
		{
			get
			{
				return _BarColor;
			}
			set
			{
				_BarColor = value;
				Invalidate();
			}
		}

		[Category("自定义")]
		[Description("滑块颜色")]
		public Color SliderColor
		{
			get
			{
				return _SliderColor;
			}
			set
			{
				_SliderColor = value;
				Invalidate();
			}
		}

		[Category("自定义")]
		[Description("是否是圆角\r\n默认：是")]
		public bool IsRound
		{
			get
			{
				return _IsRound;
			}
			set
			{
				_IsRound = value;
				Invalidate();
			}
		}

		[Category("自定义")]
		[Description("控件方向")]
		public Orientation Orientation
		{
			get
			{
				return _Orientation;
			}
			set
			{
				if (_Orientation != value)
				{
					_Orientation = value;
					if (_Orientation == Orientation.Horizontal)
					{
						base.Size = new Size(base.Size.Height, base.Size.Width);
					}
					else
					{
						base.Size = new Size(base.Size.Width, base.Size.Height);
					}
					Invalidate();
				}
			}
		}

		[Category("自定义")]
		[Description("背景条的长度")]
		public int BarSize
		{
			get
			{
				return _BarSize;
			}
			set
			{
				if (_BarSize != value)
				{
					_BarSize = value;
					if (_BarSize < 1)
					{
						_BarSize = 1;
					}
					if (_Orientation == Orientation.Horizontal)
					{
						base.Size = new Size(base.Width, _BarSize);
					}
					else
					{
						base.Size = new Size(_BarSize, base.Height);
					}
				}
			}
		}

		[Category("自定义")]
		[Description("背景条的弧线半径")]
		public int BarRadius
		{
			get
			{
				return _BarRadius;
			}
			set
			{
				_BarRadius = value;
				Invalidate();
			}
		}

		[Category("自定义")]
		[Description("滑块与背景条间隙的间隔")]
		public int Interval
		{
			get
			{
				return _Interval;
			}
			set
			{
				_Interval = value;
				Invalidate();
			}
		}

		[Category("自定义")]
		[Description("滑块位置")]
		[Browsable(false)]
		public float SliderPosition { get; set; }

		[Category("自定义")]
		[Description("显示长度/每页长度")]
		public float PageSize
		{
			get
			{
				return _PageSize;
			}
			set
			{
				_PageSize = value;
				CustomResize();
				ChangeSliderLocation();
				Invalidate();
			}
		}

		[Category("自定义")]
		[Description("文档长度")]
		public float DocSize
		{
			get
			{
				return _DocSize;
			}
			set
			{
				_DocSize = value;
				CustomResize();
				ChangeSliderLocation();
				Invalidate();
			}
		}

		[Category("自定义")]
		[Description("滑块可移动距离")]
		[Browsable(false)]
		public float SliderMoveRange { get; private set; }

		[Category("自定义")]
		[Description("滑块长度")]
		[Browsable(false)]
		public float SliderLength { get; private set; }

		[Category("自定义")]
		[Description("文档位置")]
		[Browsable(false)]
		public float DocPosition
		{
			get
			{
				return _DocPosition;
			}
			set
			{
				_DocPosition = value;
				ShowPositionToPosition();
				Invalidate();
			}
		}

		[Category("自定义")]
		[Description("鼠标滚轮一格的步进")]
		public float ScrollInterval
		{
			get
			{
				return _ScrollInterval;
			}
			set
			{
				_ScrollInterval = value;
				Invalidate();
			}
		}

		[Category("DemoUI")]
		[Description("滑块最小长度\r\n默认：20")]
		public float SliderMiniSize { get; set; } = 20f;

		public event CustomScrollEventHandler CustomScroll;

		public CustomScrollBar()
		{
			SetStyle(ControlStyles.AllPaintingInWmPaint, value: true);
			SetStyle(ControlStyles.OptimizedDoubleBuffer, value: true);
			SetStyle(ControlStyles.SupportsTransparentBackColor, value: true);
			CreateControl();
		}

		protected override void SetBoundsCore(int x, int y, int width, int height, BoundsSpecified specified)
		{
			base.SetBoundsCore(x, y, (_Orientation == Orientation.Vertical) ? _BarSize : width, (_Orientation == Orientation.Horizontal) ? _BarSize : height, specified);
		}

		private void CustomResize()
		{
			fPageDocRatio = _PageSize / _DocSize;
			fCapWidth = (_IsRound ? _BarSize : 0);
			fCapHalfWidth = fCapWidth / 2f;
			if (_Orientation == Orientation.Vertical)
			{
				SliderLength = fPageDocRatio * ((float)base.Height - fCapWidth);
				if (SliderLength < SliderMiniSize)
				{
					SliderLength = SliderMiniSize;
				}
				SliderMoveRange = (float)base.Height - fCapWidth - SliderLength;
			}
			else
			{
				SliderLength = fPageDocRatio * ((float)base.Width - fCapWidth);
				if (SliderLength < SliderMiniSize)
				{
					SliderLength = SliderMiniSize;
				}
				SliderMoveRange = (float)base.Width - fCapWidth - SliderLength;
			}
			fShowScrollRatio = ((SliderMoveRange == 0f) ? 0f : ((_DocSize - _PageSize) / SliderMoveRange));
		}

		private void ShowPositionToPosition()
		{
			CustomResize();
			SliderPosition = ((fShowScrollRatio == 0f) ? 0f : (_DocPosition / fShowScrollRatio));
		}

		private void ChangeSliderLocation()
		{
			float num = (float)base.Height - fCapWidth;
			float num2 = SliderPosition + SliderLength;
			if (num2 > num && num > 0f)
			{
				SliderPosition -= num2 - num;
				_DocPosition = SliderPosition * fShowScrollRatio;
			}
		}

		protected override void OnPaint(PaintEventArgs e)
		{
			base.OnPaint(e);
			CustomResize();
			e.Graphics.SmoothingMode = SmoothingMode.HighQuality;
			Pen pen = new Pen(_BarColor, fCapWidth);
			Pen pen2 = new Pen(_SliderColor, fCapWidth - (float)(_Interval * 2));
			if (_IsRound)
			{
				pen.StartCap = LineCap.Round;
				pen.EndCap = LineCap.Round;
				pen2.StartCap = LineCap.Round;
				pen2.EndCap = LineCap.Round;
			}
			if (_Orientation == Orientation.Horizontal)
			{
				e.Graphics.DrawLine(pen, fCapHalfWidth, base.Height / 2, (float)base.Width - fCapHalfWidth, base.Height / 2);
				e.Graphics.DrawLine(pen2, SliderPosition + fCapHalfWidth, base.Height / 2, SliderPosition + SliderLength - fCapHalfWidth, base.Height / 2);
			}
			else
			{
				e.Graphics.DrawLine(pen, base.Width / 2, fCapHalfWidth, base.Width / 2, (float)base.Height - fCapHalfWidth);
				e.Graphics.DrawLine(pen2, base.Width / 2, SliderPosition + fCapHalfWidth, base.Width / 2, SliderPosition + SliderLength + fCapHalfWidth);
			}
		}

		private int CheckMousePositionInSlider(Point point)
		{
			if (_DocSize > _PageSize)
			{
				float sliderPosition = SliderPosition;
				float num = SliderPosition + SliderLength;
				float num2;
				float num3;
				if (_Orientation == Orientation.Vertical)
				{
					num2 = point.Y;
					num3 = base.Height;
				}
				else
				{
					num2 = point.X;
					num3 = base.Width;
				}
				if (num2 > 0f && num2 < sliderPosition)
				{
					return 0;
				}
				if (num2 > sliderPosition && num2 < num)
				{
					return 1;
				}
				if (num2 > num && num2 < num3)
				{
					return 2;
				}
				return -1;
			}
			return -1;
		}

		protected override void OnMouseDown(MouseEventArgs e)
		{
			base.OnMouseDown(e);
			Select();
			switch (CheckMousePositionInSlider(e.Location))
			{
			case 0:
				_DocPosition -= _PageSize;
				if (_DocPosition < 0f)
				{
					_DocPosition = 0f;
				}
				ShowPositionToPosition();
				Invalidate();
				CustomScroll?.Invoke(this, new CustomEventArgs(_DocPosition));
				break;
			case 1:
				mouseStatus = MouseStatus.Down;
				if (_Orientation == Orientation.Vertical)
				{
					fAbove = (float)e.Location.Y - SliderPosition;
				}
				else
				{
					fAbove = (float)e.Location.X - SliderPosition;
				}
				break;
			case 2:
				_DocPosition += _PageSize;
				ShowPositionToPosition();
				if (SliderPosition > SliderMoveRange)
				{
					SliderPosition = SliderMoveRange;
					_DocPosition = SliderPosition * fShowScrollRatio;
				}
				Invalidate();
				CustomScroll?.Invoke(this, new CustomEventArgs(_DocPosition));
				break;
			}
		}

		protected override void OnMouseMove(MouseEventArgs e)
		{
			base.OnMouseMove(e);
			if (mouseStatus == MouseStatus.Down)
			{
				if (_Orientation == Orientation.Vertical)
				{
					SliderPosition = (float)e.Location.Y - fAbove;
				}
				else
				{
					SliderPosition = (float)e.Location.X - fAbove;
				}
				if (SliderPosition < 0f)
				{
					SliderPosition = 0f;
				}
				if (SliderPosition > SliderMoveRange)
				{
					SliderPosition = SliderMoveRange;
				}
				_DocPosition = SliderPosition * fShowScrollRatio;
				Invalidate();
				CustomScroll?.Invoke(this, new CustomEventArgs(_DocPosition));
			}
		}

		protected override void OnMouseUp(MouseEventArgs e)
		{
			base.OnMouseUp(e);
			mouseStatus = MouseStatus.Up;
		}

		protected override void OnMouseWheel(MouseEventArgs e)
		{
			base.OnMouseWheel(e);
			if (!(_DocSize > _PageSize))
			{
				return;
			}
			bool num = e.Delta <= 0;
			_ = Convert.ToSingle(Math.Abs(e.Delta)) / 120f;
			if (num)
			{
				_DocPosition += _ScrollInterval;
				ShowPositionToPosition();
				if (SliderPosition > SliderMoveRange)
				{
					SliderPosition = SliderMoveRange;
					_DocPosition = SliderPosition * fShowScrollRatio;
				}
				Invalidate();
				CustomScroll?.Invoke(this, new CustomEventArgs(_DocPosition));
			}
			else
			{
				_DocPosition -= _ScrollInterval;
				if (_DocPosition < 0f)
				{
					_DocPosition = 0f;
				}
				ShowPositionToPosition();
				Invalidate();
				CustomScroll?.Invoke(this, new CustomEventArgs(_DocPosition));
			}
		}
	}
	public class CustomStateButton : Control
	{
		private System.Windows.Forms.Timer timer;

		private int count;

		private Image _FailImage;

		private Image _SuccessImage;

		private Image _NormalImage;

		private Image _UpdatingImage;

		private ButtonStateEnum _buttonState;

		private string _DoingText = "";

		private string _NormalText = "";

		private int _Percent;

		public override Color BackColor { get; set; } = Color.Transparent;

		[Category("自定义")]
