		public ButtonStateEnum ButtonState
		{
			get
			{
				return _buttonState;
			}
			set
			{
				if (_buttonState != value)
				{
					_buttonState = value;
					count = 0;
					Text = _DoingText;
					if (_buttonState == ButtonStateEnum.Updating)
					{
						timer.Start();
						_Percent = 0;
					}
					if (_buttonState == ButtonStateEnum.Doing)
					{
						timer.Start();
					}
					if (_buttonState == ButtonStateEnum.Fail)
					{
						timer.Stop();
					}
					Invalidate();
				}
			}
		}

		[Category("自定义")]
