		public CustomStateButton()
		{
			SetStyle(ControlStyles.AllPaintingInWmPaint, value: true);
			SetStyle(ControlStyles.OptimizedDoubleBuffer, value: true);
			SetStyle(ControlStyles.SupportsTransparentBackColor, value: true);
			CreateControl();
			if (timer == null)
			{
				timer = new System.Windows.Forms.Timer();
				timer.Interval = 600;
				timer.Tick += Timer_Tick;
			}
			timer.Start();
		}

		private void Timer_Tick(object sender, EventArgs e)
		{
			if (_buttonState == ButtonStateEnum.Doing || _buttonState == ButtonStateEnum.Updating)
			{
				if (count < 3)
				{
					count++;
					Text += ".";
				}
				else
				{
					count = 0;
					Text = _DoingText;
				}
				Invalidate();
			}
		}

		protected override void SetBoundsCore(int x, int y, int width, int height, BoundsSpecified specified)
		{
			int val = ((_FailImage != null) ? _FailImage.Width : 0);
			int val2 = ((_FailImage != null) ? _FailImage.Height : 0);
			int val3 = ((_SuccessImage != null) ? _SuccessImage.Width : 0);
			int val4 = ((_SuccessImage != null) ? _SuccessImage.Height : 0);
			int val5 = ((_NormalImage != null) ? _NormalImage.Width : 0);
			int val6 = ((_NormalImage != null) ? _NormalImage.Height : 0);
			int val7 = Math.Max(val, val3);
			val7 = Math.Max(val7, val5);
			val7 = ((val7 == 0) ? width : val7);
			int val8 = Math.Max(val2, val4);
			val8 = Math.Max(val8, val6);
			val8 = ((val8 == 0) ? height : val8);
			base.SetBoundsCore(x, y, val7, val8, specified);
		}

		protected override void OnPaint(PaintEventArgs e)
		{
			base.OnPaint(e);
			e.Graphics.SmoothingMode = SmoothingMode.HighQuality;
			Image image = null;
			if (_buttonState == ButtonStateEnum.Normal || _buttonState == ButtonStateEnum.Doing)
			{
				image = _NormalImage;
			}
			else if (_buttonState == ButtonStateEnum.Success || _buttonState == ButtonStateEnum.PairSuccess)
			{
				image = _SuccessImage;
			}
			else if (_buttonState == ButtonStateEnum.Fail)
			{
				image = _FailImage;
			}
			else if (_buttonState == ButtonStateEnum.Updating)
			{
				image = _NormalImage;
			}
			if (image == null)
			{
				SolidBrush solidBrush = new SolidBrush(BackColor);
				e.Graphics.FillRectangle(solidBrush, e.ClipRectangle);
				solidBrush.Dispose();
			}
			else if (_buttonState == ButtonStateEnum.Updating)
			{
				Graphics graphics = e.Graphics;
				graphics.SmoothingMode = SmoothingMode.HighQuality;
				image = _UpdatingImage;
				graphics.DrawImageUnscaledAndClipped(rect: new Rectangle(0, 0, _NormalImage.Width, _NormalImage.Height), image: _NormalImage);
				Rectangle rect = new Rectangle(0, 0, _Percent * _UpdatingImage.Width / 100, _UpdatingImage.Height);
				graphics.DrawImageUnscaledAndClipped(image, rect);
			}
			else
			{
				PointF location = new PointF((base.Size.Width - image.Size.Width) / 2, (base.Size.Height - image.Size.Height) / 2);
				RectangleF rect2 = new RectangleF(location, image.Size);
				e.Graphics.DrawImage(image, rect2);
			}
			SizeF size = CreateGraphics().MeasureString(Text, Font);
			int num = Convert.ToInt32(size.Width);
			int num2 = Convert.ToInt32(size.Height);
			PointF location2 = new PointF((base.Size.Width - num) / 2, (base.Size.Height - num2) / 2);
			RectangleF layoutRectangle = new RectangleF(location2, size);
			e.Graphics.DrawString(Text, Font, new SolidBrush(ForeColor), layoutRectangle);
		}

		protected override void OnMouseEnter(EventArgs e)
		{
			base.OnMouseEnter(e);
			if (_buttonState != ButtonStateEnum.Doing && _buttonState != ButtonStateEnum.Updating && _buttonState != ButtonStateEnum.PairSuccess)
			{
				_buttonState = ButtonStateEnum.Normal;
				Text = _NormalText;
				Invalidate();
			}
		}
	}
	public class CustomTabControl : TabControl
	{
		private Color _TabPageSelectBackColor = Color.Transparent;

		private Color _TabPageUnselectBackColor = Color.Transparent;

		private Color _TabPageSelectFontColor = Color.Orange;

		private Color _TabPageUnselectFontColor = Color.White;

		public override Color BackColor { get; set; } = Color.Transparent;

		[Category("自定义")]
		[Description("TabPage选中时背景色")]
		public Color TabPageSelectBackColor
		{
			get
			{
				return _TabPageSelectBackColor;
			}
			set
			{
				_TabPageSelectBackColor = value;
				Invalidate();
			}
		}

		[Category("自定义")]
		[Description("TabPage未选中时背景色")]
		public Color TabPageUnselectBackColor
		{
			get
			{
				return _TabPageUnselectBackColor;
			}
			set
			{
				_TabPageUnselectBackColor = value;
				Invalidate();
			}
		}

		[Category("自定义")]
		[Description("TabPage选中时字体颜色")]
		public Color TabPageSelectFontColor
		{
			get
			{
				return _TabPageSelectFontColor;
			}
			set
			{
				_TabPageSelectFontColor = value;
				Invalidate();
			}
		}

		[Category("自定义")]
		[Description("TabPage未选中时字体颜色")]
		public Color TabPageUnselectFontColor
		{
			get
			{
				return _TabPageUnselectFontColor;
			}
			set
			{
				_TabPageUnselectFontColor = value;
				Invalidate();
			}
		}

		protected override CreateParams CreateParams
		{
			get
			{
				CreateParams obj = base.CreateParams;
				obj.ExStyle |= 33554432;
				return obj;
			}
		}

		public CustomTabControl()
		{
			SetStyle(ControlStyles.UserPaint | ControlStyles.ResizeRedraw | ControlStyles.SupportsTransparentBackColor | ControlStyles.AllPaintingInWmPaint | ControlStyles.DoubleBuffer | ControlStyles.OptimizedDoubleBuffer, value: true);
			UpdateStyles();
		}

		protected override void OnPaint(PaintEventArgs e)
		{
			base.OnPaint(e);
			e.Graphics.SmoothingMode = SmoothingMode.HighQuality;
			PaintBackground(e.Graphics, base.ClientRectangle);
			PaintAllTheTabs(e);
			PaintTheSelectedTab(e);
		}

		protected void PaintBackground(Graphics g, Rectangle clipRect)
		{
			if (base.Parent != null)
			{
				clipRect.Offset(base.Location);
				PaintEventArgs e = new PaintEventArgs(g, clipRect);
				GraphicsState gstate = g.Save();
				try
				{
					g.TranslateTransform(-base.Location.X, -base.Location.Y);
					InvokePaintBackground(base.Parent, e);
					InvokePaint(base.Parent, e);
					return;
				}
				finally
				{
					g.Restore(gstate);
					clipRect.Offset(-base.Location.X, -base.Location.Y);
				}
			}
			clipRect.Offset(base.Location);
			Brush brush = new SolidBrush(_TabPageUnselectBackColor);
			g.FillRectangle(brush, clipRect);
			brush.Dispose();
		}

		private void PaintTheSelectedTab(PaintEventArgs e)
		{
			if (base.SelectedIndex != -1)
			{
				int num = 0;
				Rectangle tabRect = GetTabRect(base.SelectedIndex);
				num = tabRect.Right;
				e.Graphics.DrawLine(new Pen(_TabPageSelectBackColor), tabRect.Left, tabRect.Bottom + 1, num, tabRect.Bottom + 1);
			}
		}

		private void PaintAllTheTabs(PaintEventArgs e)
		{
			if (base.TabCount > 0)
			{
				int num = 0;
				for (num = 0; num < base.TabCount; num++)
				{
					PaintTab(e, num);
				}
			}
		}

		private GraphicsPath GetTabPath(int index)
		{
			GraphicsPath graphicsPath = new GraphicsPath();
			graphicsPath.Reset();
			if (!base.IsHandleCreated)
			{
				return graphicsPath;
			}
			Rectangle tabRect = GetTabRect(index);
			switch (base.Alignment)
			{
			default:
				graphicsPath.AddLine(tabRect.Left, tabRect.Top, tabRect.Left, tabRect.Bottom + 1);
				graphicsPath.AddLine(tabRect.Left, tabRect.Top, tabRect.Right, tabRect.Top);
				graphicsPath.AddLine(tabRect.Right, tabRect.Top, tabRect.Right, tabRect.Bottom + 1);
				graphicsPath.AddLine(tabRect.Right, tabRect.Bottom + 1, tabRect.Left, tabRect.Bottom + 1);
				return graphicsPath;
			}
		}

		private void PaintTab(PaintEventArgs e, int index)
		{
			GraphicsPath tabPath = GetTabPath(index);
			PaintTabBackground(e.Graphics, index, tabPath);
			PaintTabText(e.Graphics, index);
		}

		private void PaintTabBackground(Graphics graph, int index, GraphicsPath path)
		{
			GetTabRect(index);
			Color transparent = Color.Transparent;
			transparent = ((index != base.SelectedIndex) ? _TabPageUnselectBackColor : _TabPageSelectBackColor);
			Brush brush = new SolidBrush(transparent);
			graph.FillPath(brush, path);
			brush.Dispose();
		}

		private void PaintTabText(Graphics graph, int index)
		{
			string s = base.TabPages[index].Text;
			StringFormat stringFormat = new StringFormat();
			stringFormat.Alignment = StringAlignment.Near;
			stringFormat.LineAlignment = StringAlignment.Center;
			stringFormat.Trimming = StringTrimming.EllipsisCharacter;
			Brush brush = null;
			brush = (base.TabPages[index].Enabled ? SystemBrushes.ControlText : SystemBrushes.ControlDark);
			Font font = Font;
			if (index == base.SelectedIndex)
			{
				if (base.TabPages[index].Enabled)
				{
					brush = new SolidBrush(_TabPageSelectFontColor);
				}
			}
			else if (base.TabPages[index].Enabled)
			{
				brush = new SolidBrush(_TabPageUnselectFontColor);
			}
			Rectangle tabRect = GetTabRect(index);
			int num = Convert.ToInt32(CreateGraphics().MeasureString(base.TabPages[index].Text, font).Width);
			Rectangle rectangle = new Rectangle(tabRect.Left + (base.ItemSize.Width - num) / 2, tabRect.Top, tabRect.Width, tabRect.Height);
			graph.DrawString(s, font, brush, rectangle, stringFormat);
		}
	}
	public class CustomTabSelector : Control
	{
		private Size _ItemSize = new Size(60, 40);

		private TabControl _TabControl;

		private Image _NormalImage;

		private Image _MouseEnterImage;

		private Image _CheckedImage;

		private List<Rectangle> _tabRects;

		private MouseStatus[] mouseStatus = new MouseStatus[5]
		{
			MouseStatus.Leave,
			MouseStatus.Leave,
			MouseStatus.Leave,
			MouseStatus.Leave,
			MouseStatus.Leave
		};

		public override Color BackColor { get; set; } = Color.Transparent;

		[Category("自定义")]
		[Description("页头的大小")]
		public Size ItemSize
		{
			get
			{
				return _ItemSize;
			}
			set
			{
				if (_ItemSize != value)
				{
					_ItemSize = value;
					Invalidate();
				}
			}
		}

		[Category("自定义")]
		[Description("需要加载的导航栏")]
		public TabControl TabControl
		{
			get
			{
				return _TabControl;
			}
			set
			{
				if (_TabControl == value)
				{
					return;
				}
				_TabControl = value;
				Invalidate();
				if (_TabControl != null)
				{
					_TabControl.Deselected += delegate
					{
					};
					_TabControl.SelectedIndexChanged += delegate
					{
						Invalidate();
					};
					_TabControl.ControlAdded += delegate
					{
						Invalidate();
					};
					_TabControl.ControlRemoved += delegate
					{
						Invalidate();
					};
				}
			}
		}

		public Image NormalImage
		{
			get
			{
				return _NormalImage;
			}
			set
			{
				_NormalImage = value;
				Invalidate();
			}
		}

		public Image MouseEnterImage
		{
			get
			{
				return _MouseEnterImage;
			}
			set
			{
				_MouseEnterImage = value;
				Invalidate();
			}
		}

		public Image CheckedImage
		{
			get
			{
				return _CheckedImage;
			}
			set
			{
				_CheckedImage = value;
				Invalidate();
			}
		}

		public CustomTabSelector()
		{
			SetStyle(ControlStyles.AllPaintingInWmPaint, value: true);
			SetStyle(ControlStyles.DoubleBuffer | ControlStyles.OptimizedDoubleBuffer, value: true);
			SetStyle(ControlStyles.SupportsTransparentBackColor, value: true);
			CreateControl();
		}

		protected override void SetBoundsCore(int x, int y, int width, int height, BoundsSpecified specified)
		{
			int val = 0;
			int val2 = 0;
			val = Math.Max(val, width);
			val2 = Math.Max(val2, height);
			if (_TabControl != null && _TabControl.TabCount > 0)
			{
				_ItemSize.Width = val / _TabControl.TabCount;
				_ItemSize.Height = height;
			}
			base.SetBoundsCore(x, y, val, val2, specified);
		}

		protected override void OnResize(EventArgs e)
		{
			base.OnResize(e);
			if (_TabControl != null && _TabControl.TabCount > 0)
			{
				_ItemSize.Width = base.Width / _TabControl.TabCount;
				_ItemSize.Height = base.Height;
			}
		}

		protected override void OnPaint(PaintEventArgs e)
		{
			base.OnPaint(e);
			e.Graphics.SmoothingMode = SmoothingMode.HighQuality;
			Graphics graphics = e.Graphics;
			UpdateTabRects();
			PaintBackground(graphics);
		}

		private void PaintBackground(Graphics g)
		{
			if (_TabControl == null || _NormalImage == null)
			{
				return;
			}
			for (int i = 0; i < 5; i++)
			{
				Rectangle rect = new Rectangle(_ItemSize.Width * i, 0, _ItemSize.Width, _ItemSize.Height);
				if (_NormalImage != null && _MouseEnterImage != null && _CheckedImage != null)
				{
					Image image = _NormalImage;
					if (i == _TabControl.SelectedIndex)
					{
						image = _CheckedImage;
					}
					else if (mouseStatus[i] == MouseStatus.Enter)
					{
						image = _MouseEnterImage;
					}
					Bitmap bitmap = new Bitmap(base.Width, base.Height);
					Graphics graphics = Graphics.FromImage(bitmap);
					graphics.InterpolationMode = InterpolationMode.HighQualityBicubic;
					graphics.DrawImage(image, 0, 0, base.Width, base.Height);
					graphics.Dispose();
					image = bitmap;
					if (_TabControl.TabCount == 4 && i == 4)
					{
						image = null;
					}
					else if (_TabControl.TabCount == 4 && i == 3)
					{
						Image image2 = null;
						Bitmap bitmap2 = new Bitmap(_ItemSize.Width, _ItemSize.Height, PixelFormat.Format32bppRgb);
						Graphics graphics2 = Graphics.FromImage(bitmap2);
						Rectangle srcRect = new Rectangle(base.Width / 5 * 4, 0, base.Width / 5, image.Height);
						Rectangle destRect = new Rectangle(0, 0, _ItemSize.Width, _ItemSize.Height);
						graphics2.DrawImage(image, destRect, srcRect, GraphicsUnit.Pixel);
						PixelProcess(bitmap2);
						image2 = bitmap2;
						g.DrawImage(image2, rect);
					}
					else
					{
						Image image3 = null;
						Bitmap bitmap3 = new Bitmap(_ItemSize.Width, _ItemSize.Height, PixelFormat.Format32bppRgb);
						Graphics graphics3 = Graphics.FromImage(bitmap3);
						Rectangle srcRect2 = new Rectangle(base.Width / 5 * i, 0, base.Width / 5, image.Height);
						Rectangle destRect2 = new Rectangle(0, 0, _ItemSize.Width, _ItemSize.Height);
						graphics3.DrawImage(image, destRect2, srcRect2, GraphicsUnit.Pixel);
						PixelProcess(bitmap3);
						image3 = bitmap3;
						g.DrawImage(image3, rect);
					}
				}
			}
		}

		public static void PixelProcess(Bitmap bmp)
		{
			Color pixel = bmp.GetPixel(0, 0);
			bmp.MakeTransparent(pixel);
		}

		protected override void OnMouseUp(MouseEventArgs e)
		{
			base.OnMouseUp(e);
			if (_TabControl == null)
			{
				return;
			}
			for (int i = 0; i < _TabControl.TabCount; i++)
			{
				if (_tabRects[i].Contains(e.Location))
				{
					_TabControl.SelectedIndex = i;
				}
			}
		}

		protected override void OnMouseMove(MouseEventArgs e)
		{
			base.OnMouseMove(e);
			if (_TabControl == null || _tabRects == null)
			{
				return;
			}
			for (int i = 0; i < _TabControl.TabCount; i++)
			{
				if (_tabRects[i].Contains(e.Location))
				{
					mouseStatus[i] = MouseStatus.Enter;
					Invalidate();
				}
				else
				{
					mouseStatus[i] = MouseStatus.Leave;
					Invalidate();
				}
			}
		}

		protected override void OnMouseLeave(EventArgs e)
		{
			base.OnMouseLeave(e);
			for (int i = 0; i < mouseStatus.Length; i++)
			{
				mouseStatus[i] = MouseStatus.Leave;
			}
			Invalidate();
		}

		private void UpdateTabRects()
		{
			_tabRects = new List<Rectangle>();
			if (_TabControl != null)
			{
				_tabRects.Clear();
				_tabRects.Add(new Rectangle(0, 0, _ItemSize.Width, _ItemSize.Height));
				for (int i = 1; i < _TabControl.TabCount; i++)
				{
					_tabRects.Add(new Rectangle(_tabRects[i - 1].Right, 0, _ItemSize.Width, _ItemSize.Height));
				}
			}
		}
	}
