			}
			set
			{
				_SliderPosition = value;
				Invalidate();
			}
		}

		[Category("自定义")]
		[Description("滑条高度")]
		public int BarSize
		{
			get
			{
				return _BarSize;
			}
			set
			{
				int num = base.Size.Height - _BarSize;
				_ = base.Size.Width;
				_ = _BarSize;
				_BarSize = value;
				if (_BarSize < 1)
				{
					_BarSize = 1;
				}
				num += _BarSize;
				base.Size = new Size(base.Width, num);
			}
		}

		[Browsable(true)]
		[DefaultValue(false)]
		[DesignerSerializationVisibility(DesignerSerializationVisibility.Visible)]
		[EditorBrowsable(EditorBrowsableState.Always)]
		public override bool AutoSize
		{
			get
			{
				return _AutoSize;
			}
			set
			{
				if (_AutoSize != value)
				{
					_AutoSize = value;
					SetStyle(ControlStyles.FixedHeight, _AutoSize);
					SetStyle(ControlStyles.FixedWidth, value: false);
					OnAutoSizeChanged(EventArgs.Empty);
				}
			}
		}

		public event PointChangedEventHandler PointChanged;

		public CustomTrack()
		{
			SetStyle(ControlStyles.UserPaint | ControlStyles.ResizeRedraw | ControlStyles.SupportsTransparentBackColor | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer, value: true);
			CreateControl();
		}

		protected override void SetBoundsCore(int x, int y, int width, int height, BoundsSpecified specified)
		{
			_ = _BarSize;
			if (_AutoSize)
			{
				if ((specified & BoundsSpecified.Height) != BoundsSpecified.None)
				{
					height = DefaultSize.Height;
				}
				else if ((specified & BoundsSpecified.Width) != BoundsSpecified.None)
				{
					width = DefaultSize.Width;
				}
			}
			base.SetBoundsCore(x, y, width, height, specified);
		}

		protected override void OnPaint(PaintEventArgs e)
		{
			base.OnPaint(e);
			e.Graphics.SmoothingMode = SmoothingMode.HighQuality;
			Pen pen = new Pen(_BarColor, _BarSize);
			Pen pen2 = new Pen(_SliderColor, _BarSize);
			e.Graphics.DrawLine(pen, 0, base.Height / 2, base.Width, base.Height / 2);
			e.Graphics.DrawLine(pen2, _SliderPosition, base.Height / 2, _SliderPosition + _SliderLength, base.Height / 2);
		}

		protected override void OnMouseDown(MouseEventArgs e)
		{
			base.OnMouseDown(e);
			mouseStatus = MouseStatus.Down;
			mousePoint = e.Location;
			Invalidate();
		}

		protected override void OnMouseMove(MouseEventArgs e)
		{
			base.OnMouseMove(e);
			if (mouseStatus == MouseStatus.Down)
			{
				int num = Convert.ToInt32(e.Location.X) - Convert.ToInt32(mousePoint.X);
				_SliderPosition += num;
				_SliderPosition = ((_SliderPosition >= 0) ? _SliderPosition : 0);
				_SliderPosition = ((_SliderPosition > base.Width - _SliderLength) ? (base.Width - _SliderLength) : _SliderPosition);
				PointChanged?.Invoke(this, new CustomEventArgs(_SliderPosition));
				mousePoint = e.Location;
				Invalidate();
			}
		}

		protected override void OnMouseUp(MouseEventArgs e)
		{
			base.OnMouseUp(e);
			mouseStatus = MouseStatus.Up;
			mousePoint = e.Location;
			Invalidate();
		}

		protected override void OnMouseEnter(EventArgs e)
		{
			base.OnMouseEnter(e);
			mouseStatus = MouseStatus.Enter;
		}

		protected override void OnMouseLeave(EventArgs e)
		{
			base.OnMouseLeave(e);
			mouseStatus = MouseStatus.Leave;
		}
	}
	[DefaultEvent("ValueChanged")]
