		[Category("自定义")]
		[Description(" 滑条高度（水平）/宽度（垂直）")]
		public int BarSize
		{
			get
			{
				return _BarSize;
			}
			set
			{
				int num = base.Size.Height - _BarSize;
				int num2 = base.Size.Width - _BarSize;
				_BarSize = value;
				if (_BarSize < 1)
				{
					_BarSize = 1;
				}
				if (_Orientation == Orientation.Horizontal)
				{
					num += _BarSize;
					base.Size = new Size(base.Width, num);
				}
				else
				{
					num2 += _BarSize;
					base.Size = new Size(_BarSize, base.Height);
				}
			}
		}

