		[Browsable(true)]
		[DefaultValue(false)]
		[DesignerSerializationVisibility(DesignerSerializationVisibility.Visible)]
		[EditorBrowsable(EditorBrowsableState.Always)]
		public override bool AutoSize
		{
			get
			{
				return _AutoSize;
			}
			set
			{
				if (_AutoSize == value)
				{
					return;
				}
				_AutoSize = value;
				if (_Orientation == Orientation.Horizontal)
				{
					SetStyle(ControlStyles.FixedHeight, _AutoSize);
					SetStyle(ControlStyles.FixedWidth, value: false);
				}
				else
				{
					SetStyle(ControlStyles.FixedWidth, _AutoSize);
					SetStyle(ControlStyles.FixedHeight, value: false);
				}
				int num = originalLength;
				try
				{
					if (_Orientation == Orientation.Horizontal)
					{
						base.Height = (_AutoSize ? DefaultSize.Height : num);
					}
					else
					{
						base.Width = (_AutoSize ? DefaultSize.Height : num);
					}
				}
				finally
				{
					originalLength = num;
				}
				OnAutoSizeChanged(EventArgs.Empty);
			}
		}

		[Category("自定义")]
		[Description("控件方向垂直（Vertical）或者是水平（Horizontal）")]
