		public event ValueChangedEventHandler ValueChanged;

		public event SetValueEventHandler SetValue;

		public CustomTrackBar()
		{
			SetStyle(ControlStyles.AllPaintingInWmPaint, value: true);
			SetStyle(ControlStyles.OptimizedDoubleBuffer, value: true);
			SetStyle(ControlStyles.SupportsTransparentBackColor, value: true);
			CreateControl();
		}

		[DllImport("user32.dll", CharSet = CharSet.Auto, ExactSpelling = true)]
		private static extern int GetSystemMetrics(int nIndex);

		private void ValueToPoint()
		{
			float num = 0f;
			float num2 = 0f;
			if (_Enable)
			{
				if (_IsRound)
				{
					num = (float)_BarSize / 2f;
					num2 = _BarSize;
				}
				float num3 = Convert.ToSingle(_Value / _Step * _Step - _Minimum) / (float)(_Maximum - _Minimum);
				if (_Orientation == Orientation.Horizontal)
				{
					float num4 = num3 * ((float)base.Width - num2) + num;
					mousePoint = new PointF(num4, num);
				}
				else
				{
					float num5 = (float)base.Height - num - num3 * ((float)base.Height - num2);
					mousePoint = new PointF(num, num5);
				}
			}
		}

		private void PointToValue()
		{
			float num = 0f;
			float num2 = 0f;
			if (_Enable)
			{
				if (_IsRound)
				{
					num2 = _BarSize;
					num = (float)_BarSize / 2f;
				}
				int num3 = ((_Orientation != Orientation.Horizontal) ? Convert.ToInt32(Convert.ToSingle(mousePoint.Y - num) / ((float)base.Height - num2) * (float)(_Maximum - _Minimum) + (float)_Minimum) : Convert.ToInt32(Convert.ToSingle(mousePoint.X - num) / ((float)base.Width - num2) * (float)(_Maximum - _Minimum) + (float)_Minimum));
				num3 /= _Step;
				_Value = num3 * _Step;
				if (_Value < _Minimum)
				{
					_Value = _Minimum;
				}
				if (_Value > _Maximum)
				{
					_Value = _Maximum;
				}
				ValueChanged?.Invoke(this, new CustomEventArgs(_Value));
			}
		}

		protected override void SetBoundsCore(int x, int y, int width, int height, BoundsSpecified specified)
		{
			_ = _BarSize;
			originalLength = ((_Orientation == Orientation.Horizontal) ? height : width);
			if (_AutoSize && _Orientation == Orientation.Horizontal)
			{
				if ((specified & BoundsSpecified.Height) != BoundsSpecified.None)
				{
					height = DefaultSize.Height;
				}
				else if ((specified & BoundsSpecified.Width) != BoundsSpecified.None)
				{
					width = DefaultSize.Width;
				}
			}
			base.SetBoundsCore(x, y, width, height, specified);
		}

		public static GraphicsPath CreateRoundPath(RectangleF rect, int radius)
		{
			GraphicsPath graphicsPath = new GraphicsPath();
			int num = 1;
			graphicsPath.AddArc(rect.X, rect.Y, radius, radius, 180f, 90f);
			graphicsPath.AddArc(rect.Right - (float)radius - (float)num, rect.Y, radius, radius, 270f, 90f);
			graphicsPath.AddArc(rect.Right - (float)radius - (float)num, rect.Bottom - (float)radius - (float)num, radius, radius, 0f, 90f);
			graphicsPath.AddArc(rect.X, rect.Bottom - (float)radius - (float)num, radius, radius, 90f, 90f);
			graphicsPath.CloseFigure();
			return graphicsPath;
		}

		protected override void OnPaint(PaintEventArgs e)
		{
			base.OnPaint(e);
			ValueToPoint();
			e.Graphics.SmoothingMode = SmoothingMode.HighQuality;
			Pen pen = new Pen(_Enable ? _BarColor : _DisableColor, _BarSize);
			Pen pen2 = new Pen(_Enable ? _SliderColor : _DisableColor, _BarSize);
			float num = 0f;
			float num2 = 0f;
			if (_IsRound)
			{
				num2 = _BarSize;
				num = (float)_BarSize / 2f;
				pen.StartCap = LineCap.Round;
				pen.EndCap = LineCap.Round;
				pen2.StartCap = LineCap.Round;
				pen2.EndCap = LineCap.Round;
			}
			float num3 = 0f;
			if (_Orientation == Orientation.Horizontal)
			{
				e.Graphics.DrawLine(pen, num, (float)base.Height / 2f, (float)base.Width - num, (float)base.Height / 2f);
				num3 = mousePoint.X;
				if (num3 < num2)
				{
					num3 = num2;
				}
				if (num3 > (float)base.Width - num * 4f)
				{
					num3 = (float)base.Width - num * 4f;
				}
			}
			else
			{
				e.Graphics.DrawLine(pen, (float)base.Width / 2f, num, (float)base.Width / 2f, (float)base.Height - num);
				num3 = mousePoint.Y;
				if (num3 < num2)
				{
					num3 = num2;
				}
				if (num3 > (float)base.Height - num)
				{
					num3 = (float)base.Height - num;
				}
			}
			if (_Enable)
			{
				if (_Orientation == Orientation.Horizontal)
				{
					e.Graphics.DrawLine(pen2, num, (float)base.Height / 2f, num3, (float)base.Height / 2f);
				}
				else
				{
					e.Graphics.DrawLine(pen2, (float)base.Width / 2f, num3, (float)base.Width / 2f, (float)base.Height - num);
				}
			}
			if (!_Enable)
			{
				return;
			}
			if (TrackMode == TrackModeEnum.Draw)
			{
				PointF location = new PointF(num3 - num * 2f, (float)(base.Height - _SliderSize.Height) / 2f);
				RectangleF rect = new RectangleF(location, _SliderSize);
				using SolidBrush brush = new SolidBrush(_Enable ? _SliderColor : _DisableColor);
				using GraphicsPath path = CreateRoundPath(rect, _SliderRadius);
				e.Graphics.FillPath(brush, path);
				using Pen pen3 = new Pen(_Enable ? _SliderColor : _DisableColor, 1f);
				e.Graphics.DrawPath(pen3, path);
				return;
			}
			if (base.Enabled && TrackImage != null)
			{
				PointF location2 = new PointF(num3 - num * 2f, (float)(base.Height - _TrackImage.Height) / 2f);
				RectangleF rect2 = new RectangleF(location2, _TrackImage.Size);
				e.Graphics.DrawImage(TrackImage, rect2);
			}
		}

		protected override void OnMouseDown(MouseEventArgs e)
		{
			base.OnMouseDown(e);
			mouseStatus = MouseStatus.Down;
			mousePoint = e.Location;
			PointToValue();
			Invalidate();
		}

		protected override void OnMouseMove(MouseEventArgs e)
		{
			base.OnMouseMove(e);
			if (mouseStatus == MouseStatus.Down)
			{
				mousePoint = e.Location;
				PointToValue();
				Invalidate();
			}
		}

		protected override void OnMouseUp(MouseEventArgs e)
		{
			base.OnMouseUp(e);
			mouseStatus = MouseStatus.Up;
			SetValue?.Invoke(this, new CustomEventArgs(_Value));
		}

		protected override void OnMouseEnter(EventArgs e)
		{
			base.OnMouseEnter(e);
			mouseStatus = MouseStatus.Enter;
		}

		protected override void OnMouseLeave(EventArgs e)
		{
			base.OnMouseLeave(e);
			mouseStatus = MouseStatus.Leave;
		}
	}
