		public FormAdvancedSetting(bool isUSB, string sen, bool setting, bool calPass, bool dongleLED, byte[] dongleled)
		{
			InitializeComponent();
			sensor = sen;
			string baseDirectory = AppDomain.CurrentDomain.BaseDirectory;
			BackgroundImage = new Bitmap(baseDirectory + "\\res\\6Setting\\setting_bg.png");
			pictureBox3.BackgroundImage = (pictureBox2.BackgroundImage = new Bitmap(baseDirectory + "\\res\\7General\\title.png"));
			pictureBox_WinMouse.BackgroundImage = new Bitmap(baseDirectory + "\\res\\7General\\win_mouse.png");
			SetManualCal(calPass);
			base.ShowInTaskbar = false;
			base.StartPosition = FormStartPosition.CenterParent;
			isUsb = isUSB;
			customCheckBox_LongRange.CheckImage = new Bitmap(baseDirectory + "\\res\\7General\\on.png");
			customCheckBox_LongRange.UncheckImage = new Bitmap(baseDirectory + "\\res\\7General\\off.png");
			formResize.Resize(this);
			formMover.AddForm(this);
			label_Title.Text = LanguageFile.Dialogs[61];
			label_Title.Location = new Point((base.Width - label_Title.Width) / 2, label_Title.Location.Y);
			label_PowerModeSelect.Text = LanguageFile.Dialogs[62];
			label_PowerModeSelectTips.Text = "(" + LanguageFile.Dialogs[64] + ")";
			label_PowerModeSelectTips.Location = new Point(label_PowerModeSelect.Right, label_PowerModeSelectTips.Location.Y);
			customCheckBox_LongRange.Checked = (longRangeMode = setting);
			label_MousepadSurfaceCal.Text = LanguageFile.Dialogs[65];
			label_MousepadSurfaceCalTips.Text = "(" + LanguageFile.Dialogs[68] + ")";
			label_MousepadSurfaceCalTips.Location = new Point(label_MousepadSurfaceCal.Right, label_MousepadSurfaceCalTips.Location.Y);
			customButton_ManualCal.Text = LanguageFile.Dialogs[66];
			int right = linkLabel_SystemMouse.Right;
			linkLabel_SystemMouse.Text = LanguageFile.Dialogs[69];
			linkLabel_SystemMouse.Location = new Point(right - linkLabel_SystemMouse.Size.Width, linkLabel_SystemMouse.Location.Y);
			pictureBox_WinMouse.Location = new Point(linkLabel_SystemMouse.Left - pictureBox_WinMouse.Size.Width - 3, pictureBox_WinMouse.Location.Y);
			if (dongleLED)
			{
				dongleRGB = new CustomDongleRGB(dongleled);
				dongleRGB.CheckImage = new Bitmap(baseDirectory + "\\res\\7General\\radio_select.png");
				dongleRGB.UncheckImage = new Bitmap(baseDirectory + "\\res\\7General\\radio_unselect.png");
				dongleRGB.Location = new Point(0, 133);
				dongleRGB.LEDChange += DongleRGB_LEDChange;
				base.Controls.Add(dongleRGB);
			}
		}

		private void DongleRGB_LEDChange(object sender, int value)
		{
			DongleRGB dongleRGB = new DongleRGB
			{
				color1 = new byte[3],
				color2 = new byte[3],
				color3 = new byte[3],
				mode = (byte)value
			};
			dongleRGB.color1[0] = this.dongleRGB.Data[1];
			dongleRGB.color1[1] = this.dongleRGB.Data[2];
			dongleRGB.color1[2] = this.dongleRGB.Data[3];
			dongleRGB.color2[0] = this.dongleRGB.Data[4];
			dongleRGB.color2[1] = this.dongleRGB.Data[5];
			dongleRGB.color2[2] = this.dongleRGB.Data[6];
			dongleRGB.color3[0] = this.dongleRGB.Data[7];
			dongleRGB.color3[1] = this.dongleRGB.Data[8];
			dongleRGB.color3[2] = this.dongleRGB.Data[9];
			AdvancedChange?.Invoke(this, 1, value);
		}

		public void SetUSBMode(bool mode)
		{
			isUsb = mode;
		}

