	public class FormCalibration : Form
	{
		private FormResize formResize = new FormResize();

		private System.Windows.Forms.Timer DongleCheckTimer;

		public bool CalPass = true;

		private IContainer components;

		private CustomButton customButton_Close;

		private Label label_Title;

		private PictureBox pictureBox_Main;

		private PictureBox pictureBox_Loading;

		private CustomButton customButton_Start;

		private CustomButton customButton_Back;

		public FormCalibration()
		{
			InitializeComponent();
			string baseDirectory = AppDomain.CurrentDomain.BaseDirectory;
			BackgroundImage = new Bitmap(baseDirectory + "\\res\\6Setting\\setting_bg.png");
			pictureBox_Main.BackgroundImage = new Bitmap(baseDirectory + "\\res\\8Calibration\\cal_mouse.png");
			pictureBox_Loading.Image = new Bitmap(baseDirectory + "\\res\\8Calibration\\caling.gif");
			formResize.Resize(this);
			label_Title.Text = LanguageFile.Dialogs[70];
			customButton_Start.Text = LanguageFile.Dialogs[74];
			label_Title.Location = new Point((base.Width - label_Title.Width) / 2, label_Title.Top);
			pictureBox_Main.Location = new Point((base.Width - pictureBox_Main.Width) / 2, pictureBox_Main.Top);
			pictureBox_Loading.Location = new Point((base.Width - pictureBox_Loading.Width) / 2, pictureBox_Loading.Top);
			customButton_Start.Location = new Point((base.Width - customButton_Start.Width) / 2, customButton_Start.Top);
			customButton_Back.Visible = false;
			customButton_Back.Text = LanguageFile.Dialogs[75];
			customButton_Back.Location = new Point(base.Width / 2 - customButton_Back.Width - 20, customButton_Back.Top);
			pictureBox_Loading.Visible = false;
			DongleCheckTimer = new System.Windows.Forms.Timer();
			DongleCheckTimer.Interval = 3000;
			DongleCheckTimer.Enabled = false;
			DongleCheckTimer.Tick += DongleCheckTimer_Tick;
		}

		private void DongleCheckTimer_Tick(object sender, EventArgs e)
		{
			DongleCheckTimer.Enabled = false;
			if (!CalPass)
			{
				pictureBox_Loading.Visible = false;
				label_Title.Text = LanguageFile.Dialogs[72];
				label_Title.Location = new Point((base.Width - label_Title.Width) / 2, label_Title.Top);
				pictureBox_Main.BackgroundImage = new Bitmap(AppDomain.CurrentDomain.BaseDirectory + "\\res\\8Calibration\\pass.png");
				customButton_Back.Location = new Point((base.Width - customButton_Back.Width) / 2, customButton_Back.Top);
				customButton_Back.Visible = true;
				CalPass = true;
			}
			else
			{
				pictureBox_Loading.Visible = false;
				label_Title.Text = LanguageFile.Dialogs[73];
				label_Title.Location = new Point((base.Width - label_Title.Width) / 2, label_Title.Top);
				pictureBox_Main.BackgroundImage = new Bitmap(AppDomain.CurrentDomain.BaseDirectory + "\\res\\8Calibration\\fail.png");
				customButton_Back.Visible = true;
				customButton_Start.Text = LanguageFile.Dialogs[76];
				customButton_Start.Location = new Point(customButton_Back.Right + 40, customButton_Start.Top);
				customButton_Start.Visible = true;
				CalPass = false;
			}
		}

		private void customButton_Close_Click(object sender, EventArgs e)
		{
			Close();
		}

		private void customButton_Back_Click(object sender, EventArgs e)
		{
			Close();
		}

		private void customButton_Start_Click(object sender, EventArgs e)
		{
			customButton_Back.Visible = false;
			pictureBox_Loading.Visible = true;
			label_Title.Text = LanguageFile.Dialogs[71];
			label_Title.Location = new Point((base.Width - label_Title.Width) / 2, label_Title.Top);
			pictureBox_Main.BackgroundImage = new Bitmap(AppDomain.CurrentDomain.BaseDirectory + "\\res\\8Calibration\\cal_mouse.png");
			customButton_Start.Visible = false;
			DongleCheckTimer.Enabled = true;
		}

