	public class FormEditDialog : Form
	{
		private FormResize formResize = new FormResize();

		public string text = "";

		public Keys keys;

		public int delay;

		public bool NeedUpdate;

		public string ComboString = "";

		public List<byte> ComboData = new List<byte>();

		private bool CheckBoxVisible;

		private bool InsertKey;

		private bool InsertDelay;

		private int time;

		private KeyboardHook keyboardHook = new KeyboardHook();

		public KeyboardCode keyboardCode = new KeyboardCode();

		private List<KeyboardCode> keyboardCodes = new List<KeyboardCode>();

		private IContainer components;

		private Label label1;

		private CustomButton customButton_Close;

		private TextBox Dlg_textBox1;

		private CustomCheckBox customCheckBox_Shift;

		private CustomCheckBox customCheckBox_Ctrl;

		private CustomCheckBox customCheckBox_Alt;

		private CustomCheckBox customCheckBox_Win;

		private Label label_Shift;

		private Label label_Ctrl;

		private Label label_Alt;

		private Label label_Win;

		private CustomButton customButton_Confirm;

		private CustomButton customButton_Cancel;

		public FormEditDialog(string str, string[] keys, FormEditDialogType type)
		{
			InitializeComponent();
			ImageInit();
			formResize.Resize(this);
			LanguageFile.FormSetColor(this);
			base.ShowInTaskbar = false;
			base.StartPosition = FormStartPosition.CenterParent;
			label1.Text = str;
			switch (type)
			{
			case FormEditDialogType.MacroName:
				Dlg_textBox1.ImeMode = ImeMode.On;
				break;
			case FormEditDialogType.KeyEvent:
				Dlg_textBox1.MaxLength = 1;
				Dlg_textBox1.CharacterCasing = CharacterCasing.Upper;
				InsertKey = true;
				break;
			case FormEditDialogType.Delay:
				InsertDelay = true;
				break;
			case FormEditDialogType.ComboKey:
				CheckBoxVisible = true;
				Dlg_textBox1.MaxLength = 1;
				Dlg_textBox1.CharacterCasing = CharacterCasing.Upper;
				InsertKey = true;
				break;
			}
			customCheckBox_Alt.Visible = CheckBoxVisible;
			label_Alt.Visible = CheckBoxVisible;
			customCheckBox_Ctrl.Visible = CheckBoxVisible;
			label_Ctrl.Visible = CheckBoxVisible;
			customCheckBox_Shift.Visible = CheckBoxVisible;
			label_Shift.Visible = CheckBoxVisible;
			customCheckBox_Win.Visible = CheckBoxVisible;
			label_Win.Visible = CheckBoxVisible;
			if (InsertKey)
			{
				keyboardHook.KeyDown += KeyboardHook_KeyDown;
				keyboardHook.KeyUp += KeyboardHook_KeyUp;
				keyboardHook.Start(Marshal.GetHINSTANCE(Assembly.GetExecutingAssembly().GetModules()[0]));
			}
			customButton_Confirm.Text = keys[0];
			customButton_Cancel.Text = keys[1];
		}

		private void ImageInit()
		{
			string baseDirectory = AppDomain.CurrentDomain.BaseDirectory;
			BackgroundImage = new Bitmap(baseDirectory + "\\res\\7General\\message_bg.png");
			CustomButton customButton = customButton_Cancel;
			Image normalImage = (customButton_Confirm.NormalImage = new Bitmap(baseDirectory + "\\res\\7General\\ok_nr.png"));
			customButton.NormalImage = normalImage;
			CustomButton customButton2 = customButton_Cancel;
			normalImage = (customButton_Confirm.MouseDownImage = new Bitmap(baseDirectory + "\\res\\7General\\ok_down.png"));
			customButton2.MouseDownImage = normalImage;
			CustomButton customButton3 = customButton_Cancel;
			normalImage = (customButton_Confirm.MouseEnterImage = new Bitmap(baseDirectory + "\\res\\7General\\ok_enter.png"));
			customButton3.MouseEnterImage = normalImage;
			customButton_Close.NormalImage = new Bitmap(baseDirectory + "\\res\\7General\\setting_close_nr.png");
			customButton_Close.MouseDownImage = new Bitmap(baseDirectory + "\\res\\7General\\setting_close_down.png");
			customButton_Close.MouseEnterImage = new Bitmap(baseDirectory + "\\res\\7General\\setting_close_enter.png");
			CustomCheckBox customCheckBox = customCheckBox_Alt;
			CustomCheckBox customCheckBox2 = customCheckBox_Ctrl;
			CustomCheckBox customCheckBox3 = customCheckBox_Shift;
			Image image4 = (customCheckBox_Win.CheckImage = new Bitmap(baseDirectory + "\\res\\7General\\check_select.png"));
			Image image6 = (customCheckBox3.CheckImage = image4);
			normalImage = (customCheckBox2.CheckImage = image6);
			customCheckBox.CheckImage = normalImage;
			CustomCheckBox customCheckBox4 = customCheckBox_Alt;
			CustomCheckBox customCheckBox5 = customCheckBox_Ctrl;
			CustomCheckBox customCheckBox6 = customCheckBox_Shift;
