		public FormMain(DeviceAllInfo deviceAllInfo, DriveConfig.DriveParam config)
		{
			SelectedDeviceInfo = default(DeviceAllInfo);
			SelectedDeviceInfo = deviceAllInfo;
			FormInit(config);
			deviceParam = driveParam.DeviceParams[SelectedDeviceInfo.deviceIndex];
			UIInit();
			UIInit(SelectedDeviceInfo.deviceIndex);
		}

		public FormMain(DriveConfig.DriveParam config)
		{
			FormInit(config);
			SelectedDeviceInfo = default(DeviceAllInfo);
			SelectedDeviceInfo.deviceInfo.CID = (byte)driveParam.CID;
			SelectedDeviceInfo.deviceInfo.MID = (byte)driveParam.DeviceParams[0].MID;
			SelectedDeviceInfo.deviceIndex = 0;
			deviceParam = driveParam.DeviceParams[0];
			UIInit();
			UIInit(SelectedDeviceInfo.deviceIndex);
			customButton_HomePage.Visible = false;
		}

		private void FormInit(DriveConfig.DriveParam config)
		{
			InitializeComponent();
			ThisHandleCreate = false;
			SetStyles();
			formMover.AddForm(this);
			LanguageFile.FormSetColor(this);
			driveParam = config;
			TabControl_Init();
			systemLog = new SystemLog("Device" + (SelectedDeviceInfo.deviceIndex + 1) + "_log");
			if (languageFile.GetLanguageFileCount() == 0)
			{
				systemLog.WriteLog("no language file  detected,please check first!!");
				Close();
			}
			else
			{
				systemLog.WriteLog("find language file!!");
			}
			systemLog.WriteLog("GetDpi:" + FormResize.GetDpi());
			languageFile.SetLanguage(languageFile.LanguageIndex, this);
			keyboardHook.KeyDown += KeyboardHook_KeyDown;
			keyboardHook.KeyUp += KeyboardHook_KeyUp;
			base.FormClosed += FormMain_FormClosed;
		}

		private void FormMain_FormClosed(object sender, FormClosedEventArgs e)
		{
			System_Exit(null, null);
		}

		private void SetStyles()
		{
			SetStyle(ControlStyles.UserPaint | ControlStyles.ResizeRedraw | ControlStyles.AllPaintingInWmPaint | ControlStyles.DoubleBuffer | ControlStyles.OptimizedDoubleBuffer, value: true);
			UpdateStyles();
			base.AutoScaleMode = AutoScaleMode.None;
		}

		private void UIInit()
		{
			SetSaveButton(enable: false);
			XIn1Point = _3In1_Main.Location;
			ImageListInit();
			ListViewKeysImageInit();
			GetComboBoxConfigItems();
			ReadLocalMacroInit();
			Panel_CycleProcess_Init();
			LoadToolStripMenuItem();
			TimerInit();
			gConnectState = ConnectState.Disconnect;
		}

		private void SetButton(Control father)
		{
			foreach (Control control in father.Controls)
			{
				if (control is CustomButton)
				{
					((CustomButton)control).MouseEnter += Button_MouseEnter;
				}
				else if (control.HasChildren)
				{
					SetButton(control);
				}
			}
		}

		private void Button_MouseEnter(object sender, EventArgs e)
		{
			CustomButton customButton = (CustomButton)sender;
			if (customButton.Name == "customButton_HomePage")
			{
				toolTip.SetToolTip(customButton, LanguageFile.Dialogs[98]);
			}
			else if (Convert.ToInt32(CreateGraphics().MeasureString(customButton.Text, customButton.Font).Width) >= customButton.Width)
			{
				toolTip.SetToolTip(customButton, customButton.Text);
			}
		}

		private void DPIInit()
		{
			dpiControl1.MaxGrade = deviceParam.DPIMaxGrade;
			dpiControl1.Step = deviceParam.SensorDPI.Step[0];
			dpiControl1.MinValue = deviceParam.SensorDPI.Min[0];
			dpiControl1.MaxValue = deviceParam.SensorDPI.Max[deviceParam.SensorDPI.Max.Count - 1];
			dpiControl1.ValueChange -= UpdateFlashDataMap_ValueChange;
			dpiControl1.ValueChange += UpdateFlashDataMap_ValueChange;
			dpiControl1.UpdateUIFlag = false;
		}

		private void ButtonFunctionInit(int value)
		{
			ButtonFunctions.Clear();
			int num = value / 10;
			bool flag = value % 10 == 1;
			for (int i = 1; i < 17; i++)
			{
				foreach (Control control in panel_Device.Controls)
				{
					if (!(control is CustomButton))
					{
						continue;
					}
					CustomButton customButton = (CustomButton)control;
					customButton.NormalImage = new Bitmap(AppDomain.CurrentDomain.BaseDirectory + "\\res\\2Button\\mouse_key_nr.png");
					customButton.MouseDownImage = new Bitmap(AppDomain.CurrentDomain.BaseDirectory + "\\res\\2Button\\mouse_key_down.png");
					customButton.MouseEnterImage = new Bitmap(AppDomain.CurrentDomain.BaseDirectory + "\\res\\2Button\\mouse_key_enter.png");
					if (customButton.Name == "customButton" + i)
					{
						customButton.Location = new Point(deviceParam.KeyParams[i - 1].point.X, deviceParam.KeyParams[i - 1].point.Y);
						customButton.Tag = (i - 1).ToString();
						customButton.Click -= Button_Click;
						customButton.Click += Button_Click;
						if (i < num + 1 || ((i > 12) & flag))
						{
							customButton.Visible = true;
						}
						else
						{
							customButton.Visible = false;
						}
						customButton.Text = i.ToString();
						customButton.ForeColor = driveParam.NumClr;
						ButtonFunctions.Add(customButton);
						break;
					}
				}
			}
			customKeyFunction1.ScrollSet = flag;
			customKeyFunction1.ButtonCount = num;
			customKeyFunction1.ValueChange -= FlashDataMap_ValueChange;
			customKeyFunction1.ValueChange += FlashDataMap_ValueChange;
			customKeyFunction1.UpdateUIFlag = false;
		}

		private void Button_Click(object sender, EventArgs e)
		{
			if (GetDeviceOnline())
			{
				int num = int.Parse(((CustomButton)sender).Tag.ToString());
				customKeyFunction1.SelectedIndex = deviceParam.KeyParams[num].index;
			}
		}

		private void Panel_CycleProcess_Init()
		{
			foreach (CustomRadioButton control in panel_CycleProcess.Controls)
			{
				control.CheckedChanged += CustomRadioButton_CheckedChanged;
			}
		}

