				{
					tabPage_Sensor.Controls.Remove(_2In1_Main);
				}
				if (!tabPage_Sensor.Controls.Contains(_3In1_Main))
				{
					_3In1_Main.Location = XIn1Point;
					tabPage_Sensor.Controls.Add(_3In1_Main);
				}
			}
			else
			{
				if (tabPage_Sensor.Controls.Contains(_3In1_Main))
				{
					tabPage_Sensor.Controls.Remove(_3In1_Main);
				}
				if (!tabPage_Sensor.Controls.Contains(_2In1_Main))
				{
					_2In1_Main.Location = XIn1Point;
					tabPage_Sensor.Controls.Add(_2In1_Main);
				}
			}
		}

		private void LoadToolStripMenuItem()
		{
			FieldInfo[] fields = GetType().GetFields(BindingFlags.Instance | BindingFlags.NonPublic);
			for (int i = 0; i < fields.Length; i++)
			{
				if (!(fields[i].FieldType.Name == "ToolStripMenuItem"))
				{
					continue;
				}
				ToolStripMenuItem toolStripMenuItem = (ToolStripMenuItem)fields[i].GetValue(this);
				for (int j = 0; j < languageFile.ToolStripMenuItemLabelStructs.Count; j++)
				{
					if (toolStripMenuItem.Name == languageFile.ToolStripMenuItemLabelStructs[j].Name)
					{
						toolStripMenuItem.Text = languageFile.ToolStripMenuItemLabelStructs[j].Text;
						break;
					}
				}
			}
		}

		private void ReadLocalMacroInit()
		{
