			adjustControl_B.Value = pixel.B;
			gFlashDataMap.ledBar.color[0] = pixel.R;
			gFlashDataMap.ledBar.color[1] = pixel.G;
			gFlashDataMap.ledBar.color[2] = pixel.B;
			UpdataUSBData();
			UpdateLEDFlag = false;
		}

