		private int GetMacroKeyContextIndex(int SelectIndex)
		{
			int num = 0;
			for (int i = 0; i <= SelectIndex; i++)
			{
				if (!listView_Keys.Items[i].Text.Contains("ms"))
				{
					num++;
				}
			}
			return num;
		}

