		private void customRecordMacro1_Click(object sender, EventArgs e)
		{
			if (customListView_Macro.SelectedItems.Count == 0)
			{
				customRecordMacro1.Checked = false;
				new FormDialog(LanguageFile.Dialogs[12]).ShowDialog();
				return;
			}
			if (customRadioButton_DefaultDelay.Checked && int.Parse(textBox_AutoDelayTime.Text) < 10)
			{
				new FormDialog(LanguageFile.Dialogs[91]).ShowDialog();
				return;
			}
			customRecordMacro1.Checked = !customRecordMacro1.Checked;
			textBox_CycleTimes.Visible = !customRecordMacro1.Checked;
			if (!customRecordMacro1.Checked)
			{
				customTabSelector_Main.Enabled = true;
				SetSaveButton(enable: true);
				textBox_AutoDelayTime.Visible = true;
				customListView_Macro.Enabled = true;
				keyboardHook.Stop();
			}
			else
			{
				listView_Keys.Items.Clear();
				customListView_Macro.Enabled = false;
				textBox_AutoDelayTime.Visible = false;
				customTabSelector_Main.Enabled = false;
				macroKeyDriver = new MacroKeyDriver();
				keyboardHook.Start(Marshal.GetHINSTANCE(Assembly.GetExecutingAssembly().GetModules()[0]));
			}
		}

		private void customButton_Save_Click(object sender, EventArgs e)
		{
			if (IsRecordingMacro())
			{
				return;
			}
			MacroKeyAndCycle OutParam = new MacroKeyAndCycle(0);
			byte cycleTimes = 0;
			if (customRadioButton_CycleTimes.Checked)
			{
				if (textBox_CycleTimes.Text == "" || textBox_CycleTimes.Text == "0")
				{
					textBox_CycleTimes.Text = 1.ToString();
				}
				cycleTimes = Convert.ToByte(textBox_CycleTimes.Text);
			}
			else if (customRadioButton_UntilKeyPressed.Checked)
			{
				cycleTimes = byte.MaxValue;
			}
			else if (customRadioButton_UntilKeyReleased.Checked)
			{
				cycleTimes = 254;
			}
			else if (customRadioButton_UntilThisKeyPressed.Checked)
			{
				cycleTimes = 253;
			}
			MacroKeyDriver.Copy(macroKeyDriver.macroKey, ref OutParam, customListView_Macro.SelectedItems[0].Text, cycleTimes);
			MacroKeyAndCycleList.RemoveAt(customListView_Macro.SelectedItems[0].Index);
			MacroKeyAndCycleList.Insert(customListView_Macro.SelectedItems[0].Index, OutParam);
			LoadMacroKeyContext(OutParam);
			SetSaveButton(enable: false);
			languageFile.KeyFunctionSubStructs[6].Clear();
			for (int i = 0; i < customListView_Macro.Items.Count; i++)
			{
				KeyFunctionStruct item = new KeyFunctionStruct
				{
					name = customListView_Macro.Items[i].Text
				};
				languageFile.KeyFunctionSubStructs[6].Add(item);
			}
			customKeyFunction1.UpdateMacro(languageFile, customListView_Macro.SelectedItems[0].Index);
			MacroFile.SaveLocalMacroKey(MacroKeyAndCycleList);
		}

		private void customKeyFunction1_UpdateMacroUI(object sender, MacroKeyAndCycle macroKeyAndCycle)
		{
			customListView_Macro.Items.Clear();
			languageFile.KeyFunctionSubStructs[6].Clear();
			for (int i = 0; i < MacroKeyAndCycleList.Count; i++)
			{
				KeyFunctionStruct item = default(KeyFunctionStruct);
				customListView_Macro.Items.Add(MacroKeyAndCycleList[i].name);
				item.name = customListView_Macro.Items[i].Text;
				languageFile.KeyFunctionSubStructs[6].Add(item);
			}
		}

		private void ToolStripMenuItem_ExportMacro_Click(object sender, EventArgs e)
		{
			string text = "Compx Inc ";
			bool flag = false;
			for (int i = 0; i < MacroKeyAndCycleList[customListView_Macro.SelectedItems[0].Index].macroKey.contextCount; i++)
			{
				if (MacroKeyAndCycleList[customListView_Macro.SelectedItems[0].Index].macroKey.context[i].type == 5)
				{
					flag = true;
					break;
				}
			}
			if (flag)
			{
				text += "Move-XY";
			}
			string fileName = customListView_Macro.Items[customListView_Macro.SelectedItems[0].Index].Text;
			MacroFile.ExportMacroFile(MacroKeyAndCycleList[customListView_Macro.SelectedItems[0].Index], fileName, text);
		}

		private void ToolStripMenuItem_ImportMacro_Click(object sender, EventArgs e)
		{
			string text = "Compx Inc ";
			int index = 0;
			for (int i = 0; i < LanguageFile.ComboBoxStructs.Count; i++)
			{
				if (customComboBox_InsertEvent.Name == LanguageFile.ComboBoxStructs[i].Name)
				{
					index = i;
					break;
				}
			}
			for (int j = 0; j < customComboBox_InsertEvent.Item.Count; j++)
			{
				if (LanguageFile.ComboBoxStructs[index].Values[j] == 327680)
				{
					text += "Move-XY";
					break;
				}
			}
			MacroKeyAndCycle OutMacroKeyAndCycle = new MacroKeyAndCycle(0);
			switch (MacroFile.ImportMacroFile(ref OutMacroKeyAndCycle, text))
			{
			case 0:
			{
				string name = OutMacroKeyAndCycle.name;
				if (!MacroSameNameDialog(name))
				{
					customListView_Macro.Items.Add(name);
					MacroKeyAndCycleList.Add(OutMacroKeyAndCycle);
					KeyFunctionStruct item = new KeyFunctionStruct
					{
						name = name
					};
					languageFile.KeyFunctionSubStructs[6].Add(item);
					LoadMacroKeyContext(OutMacroKeyAndCycle);
				}
				break;
			}
			case 1:
				new FormDialog(LanguageFile.Dialogs[8], DialogButtons.OK).ShowDialog();
				break;
			}
		}

		private void ToolStripMenuItem_Rename_Click(object sender, EventArgs e)
		{
			FormEditDialog formEditDialog = new FormEditDialog(keys: new string[2]
			{
				LanguageFile.Dialogs[37],
				LanguageFile.Dialogs[38]
			}, str: LanguageFile.Dialogs[11], type: FormEditDialogType.MacroName);
			formEditDialog.ShowDialog();
			if (formEditDialog.text != null && formEditDialog.NeedUpdate && !MacroSameNameDialog(formEditDialog.text))
			{
				customListView_Macro.Items[customListView_Macro.SelectedItems[0].Index].Text = formEditDialog.text;
				int index = customListView_Macro.SelectedItems[0].Index;
				MacroKeyAndCycle OutParam = new MacroKeyAndCycle(0);
				MacroKeyDriver.Copy(MacroKeyAndCycleList[index].macroKey, ref OutParam, formEditDialog.text, MacroKeyAndCycleList[index].CycleTimes);
				MacroKeyAndCycleList.RemoveAt(index);
				MacroKeyAndCycleList.Insert(index, OutParam);
				languageFile.KeyFunctionSubStructs[6].Clear();
				for (int i = 0; i < customListView_Macro.Items.Count; i++)
				{
					KeyFunctionStruct item = new KeyFunctionStruct
					{
						name = customListView_Macro.Items[i].Text
					};
					languageFile.KeyFunctionSubStructs[6].Add(item);
				}
				customKeyFunction1.UpdateMacro(languageFile, index);
			}
		}

		private bool IsRecordingMacro()
		{
			if (customRecordMacro1.Checked)
			{
				new FormDialog(LanguageFile.Dialogs[13]).ShowDialog();
			}
			return customRecordMacro1.Checked;
		}

		private bool MacroSameNameDialog(string name)
		{
			for (int i = 0; i < customListView_Macro.Items.Count; i++)
			{
				if (name == customListView_Macro.Items[i].Text)
				{
					new FormDialog(LanguageFile.Dialogs[10]).ShowDialog();
					return true;
				}
			}
			return false;
		}

		private void SetSaveButton(bool enable)
		{
			customButton_Save.Enabled = enable;
			customButton_Save.ForeColor = (enable ? Color.White : Color.FromArgb(157, 157, 157));
			customButton_Save.NormalImage = (enable ? customButton_Save.MouseDownImage : btnSaveNormal);
		}

		private void textBox_AutoDelayTime_TextChanged(object sender, EventArgs e)
		{
			if (!(textBox_AutoDelayTime.Text == "") && int.Parse(textBox_AutoDelayTime.Text) > 65535)
			{
				textBox_AutoDelayTime.Text = "65535";
			}
		}

		private void textBox_AutoDelayTime_KeyPress(object sender, KeyPressEventArgs e)
		{
			if (e.KeyChar != '\b' && !char.IsNumber(e.KeyChar))
			{
				e.Handled = true;
			}
		}

		private void textBox_CycleTimes_KeyPress(object sender, KeyPressEventArgs e)
		{
			if (e.KeyChar != '\b' && !char.IsNumber(e.KeyChar))
			{
				e.Handled = true;
			}
		}

		private void textBox_CycleTimes_TextChanged(object sender, EventArgs e)
		{
			if (textBox_CycleTimes.Text == "")
			{
				return;
			}
			int num = int.Parse(textBox_CycleTimes.Text);
			if (MacroKeyAndCycleList[customListView_Macro.SelectedItems[0].Index].CycleTimes < 250 && num != MacroKeyAndCycleList[customListView_Macro.SelectedItems[0].Index].CycleTimes)
			{
				if (num > 250)
				{
					textBox_CycleTimes.Text = "250";
				}
				SetSaveButton(enable: true);
			}
		}

		private void customButton17_Click(object sender, EventArgs e)
		{
			ServicePointManager.SecurityProtocol = SecurityProtocolType.Tls12;
			WebClient webClient = new WebClient();
			try
