	public class FormMoveXY : Form
	{
		private FormResize formResize = new FormResize();

		public bool NeedUpdate;

		public uint x;

		public uint y;

		public string xString;

		public string yString;

		private IContainer components;

		private Label label_X;

		private Label label_Y;

		private TextBox Dlg_textBox_X;

		private TextBox Dlg_textBox_Y;

		private CustomRadioButton customRadioButton_Left;

		private Label label_Left;

		private Label label_Right;

		private CustomRadioButton customRadioButton_Right;

		private Label label_Up;

		private CustomRadioButton customRadioButton_Up;

		private Label label_Down;

		private CustomRadioButton customRadioButton_Down;

		private CustomButton customButton_Close;

		private CustomButton customButton_Cancel;

		private CustomButton customButton_Confirm;

		private Panel panel_X;

		private Panel panel_Y;

		public FormMoveXY(string[] text, string[] keys)
		{
			InitializeComponent();
			ImageInit();
			formResize.Resize(this);
			LanguageFile.FormSetColor(this);
			label_Up.Text = text[0];
			label_Down.Text = text[1];
			label_Left.Text = text[2];
			label_Right.Text = text[3];
			customButton_Confirm.Text = keys[0];
			customButton_Cancel.Text = keys[1];
		}

		private void ImageInit()
		{
			string baseDirectory = AppDomain.CurrentDomain.BaseDirectory;
			BackgroundImage = new Bitmap(baseDirectory + "\\res\\7General\\message_bg.png");
			CustomButton customButton = customButton_Cancel;
			Image normalImage = (customButton_Confirm.NormalImage = new Bitmap(baseDirectory + "\\res\\7General\\ok_nr.png"));
			customButton.NormalImage = normalImage;
			CustomButton customButton2 = customButton_Cancel;
			normalImage = (customButton_Confirm.MouseDownImage = new Bitmap(baseDirectory + "\\res\\7General\\ok_down.png"));
			customButton2.MouseDownImage = normalImage;
			CustomButton customButton3 = customButton_Cancel;
			normalImage = (customButton_Confirm.MouseEnterImage = new Bitmap(baseDirectory + "\\res\\7General\\ok_enter.png"));
			customButton3.MouseEnterImage = normalImage;
			customButton_Close.NormalImage = new Bitmap(baseDirectory + "\\res\\7General\\setting_close_nr.png");
			customButton_Close.MouseDownImage = new Bitmap(baseDirectory + "\\res\\7General\\setting_close_down.png");
			customButton_Close.MouseEnterImage = new Bitmap(baseDirectory + "\\res\\7General\\setting_close_enter.png");
		}

		private void customButton_Close_Click(object sender, EventArgs e)
		{
			Close();
		}

		private void customButton_Confirm_Click(object sender, EventArgs e)
		{
			if (Dlg_textBox_X.Text == "")
			{
				Dlg_textBox_X.Text = 0.ToString();
			}
			if (customRadioButton_Left.Checked)
			{
				xString = label_Left.Text;
				x = (uint)(-Convert.ToInt32(Dlg_textBox_X.Text));
			}
			else if (customRadioButton_Right.Checked)
			{
				xString = label_Right.Text;
				x = (uint)Convert.ToInt32(Dlg_textBox_X.Text);
			}
			if (Dlg_textBox_Y.Text == "")
			{
				Dlg_textBox_Y.Text = 0.ToString();
			}
			if (customRadioButton_Up.Checked)
			{
				yString = label_Up.Text;
				y = (uint)(-Convert.ToInt32(Dlg_textBox_Y.Text));
			}
			else if (customRadioButton_Down.Checked)
			{
				yString = label_Down.Text;
				y = (uint)Convert.ToInt32(Dlg_textBox_Y.Text);
			}
			if (x == 0 && y == 0)
			{
				NeedUpdate = false;
			}
			else
			{
				NeedUpdate = true;
			}
			Close();
		}

		private void customButton_Cancel_Click(object sender, EventArgs e)
		{
			Close();
		}

		private void textBox_X_TextChanged(object sender, EventArgs e)
		{
			if (Dlg_textBox_X.Text != "" && int.Parse(Dlg_textBox_X.Text) > 127)
			{
				Dlg_textBox_X.Text = 127.ToString();
			}
		}

		private void textBox_X_KeyPress(object sender, KeyPressEventArgs e)
		{
			if (e.KeyChar != '\b' && !char.IsNumber(e.KeyChar))
			{
				e.Handled = true;
			}
		}

		private void textBox_Y_TextChanged(object sender, EventArgs e)
		{
			if (Dlg_textBox_Y.Text != "" && int.Parse(Dlg_textBox_Y.Text) > 127)
			{
				Dlg_textBox_Y.Text = 127.ToString();
			}
		}

		private void textBox_Y_KeyPress(object sender, KeyPressEventArgs e)
		{
			if (e.KeyChar != '\b' && !char.IsNumber(e.KeyChar))
			{
				e.Handled = true;
			}
		}

