			customButton_Close.MouseEnterImage = new Bitmap(baseDirectory + "\\res\\7General\\setting_close_enter.png");
			panel_Background.BackgroundImage = new Bitmap(baseDirectory + "\\res\\7General\\process_bg.png");
			panel_Silder.BackgroundImage = new Bitmap(baseDirectory + "\\res\\7General\\process.png");
			SetProcessVisible(visible: false);
			label_UpdatingTips.Text = LanguageFile.Dialogs[58];
			CustomButton customButton7 = customButton_Update;
			bool visible = (customButton_Confirm.Visible = false);
			customButton7.Visible = visible;
			label_UpdateTips.Text = LanguageFile.Dialogs[106];
		}

		private void SetProcessVisible(bool visible)
		{
			panel_Background.Visible = visible;
			panel_Silder.Visible = visible;
		}

		private void SetProcessValue(int value)
		{
			if (!panel_Silder.Visible)
			{
				SetProcessVisible(visible: true);
			}
			panel_Silder.Width = panel_Background.Width * value / 100;
		}

		private void UpdatingProcess()
		{
			bool result = false;
			while (updating && !result)
			{
				if (base.IsHandleCreated)
				{
					Invoke((EventHandler)delegate
					{
						UpdateTimerOut.Enabled = true;
						label_UpdatingTips.Text = LanguageFile.Dialogs[58];
						result = UsbFinder.UsbUpgrade_Start(UpdateBuffer, UpgradeHandler, 10000);
						finding = false;
						customButton_Confirm.Visible = false;
						SetProcessValue(0);
						label_UpdatingTips.Text = LanguageFile.Dialogs[58] + "：0%";
					});
				}
				Thread.Sleep(500);
			}
			pollingThread.Abort();
		}

		private void RepairProcess()
		{
			bool result = RegeditManager.GetUpdateFailInfo(out updateFialInfo);
			CXFILE_TYPE cXFILE_TYPE = (CXFILE_TYPE)updateFialInfo[0];
			DriveConfig.DeviceParam deviceParam = new DriveConfig.DeviceParam();
			for (int i = 0; i < driveParam.DeviceTotal; i++)
			{
				if (driveParam.DeviceParams[i].MID == updateFialInfo[3])
				{
					deviceParam = driveParam.DeviceParams[i];
					break;
				}
			}
			string mcu = deviceParam.MM;
			if (cXFILE_TYPE == CXFILE_TYPE.Dongle)
			{
				switch (updateFialInfo[1])
				{
				case 1:
					mcu = deviceParam.DM;
					break;
				case 2:
					mcu = deviceParam.D2M;
					break;
				case 4:
					mcu = deviceParam.D4M;
					break;
				}
			}
			result = DeviceUpdateFile.HasDeviceUpdateFile((byte)cXFILE_TYPE, "", mcu, updateFialInfo[2], (byte)deviceParam.MID, out UpdateBuffer);
			while (finding & result)
			{
				string[] array = UsbFinder.FindBootDevices(UpdateBuffer);
				if (array.Length == 1)
				{
					Invoke((EventHandler)delegate
					{
						UpdateTimerOut.Enabled = true;
						updating = true;
						label_UpdatingTips.Text = LanguageFile.Dialogs[58];
						result = UsbFinder.UsbUpgrade_Start(UpdateBuffer, UpgradeHandler, 10000);
						finding = false;
						customButton_Confirm.Visible = false;
						SetProcessValue(0);
					});
				}
				else if (array.Length == 0)
				{
					Invoke((EventHandler)delegate
					{
						updating = false;
						label_UpdatingTips.Text = LanguageFile.Dialogs[6];
						customButton_Confirm.Visible = true;
						SetProcessVisible(visible: false);
					});
				}
				else
				{
					Invoke((EventHandler)delegate
					{
						updating = false;
						label_UpdatingTips.Text = LanguageFile.Dialogs[29];
						customButton_Confirm.Visible = true;
						SetProcessVisible(visible: false);
					});
				}
				Thread.Sleep(1000);
			}
			pollingThread.Abort();
		}

		private void UpgradeDataHandler(byte[] command)
		{
			if (command[0] != 7)
			{
				return;
			}
			switch ((UpgradeState)command[1])
			{
			case UpgradeState.DownLoadFile:
				if (!updating)
				{
					updating = true;
				}
				UpdateTimerOutCnt = 0;
				SetProcessValue(command[2]);
				label_UpdatingTips.Text = LanguageFile.Dialogs[58] + "：" + command[2] + "%";
				break;
			case UpgradeState.UpgradeResult:
				if (command[2] == 1)
				{
					SetProcessValue(100);
					updateSuccess = true;
					label_UpdatingTips.Text = LanguageFile.Dialogs[56];
					RegeditManager.ClearUpdateFailInfo();
				}
				else
				{
					updateSuccess = false;
					label_UpdatingTips.Text = LanguageFile.Dialogs[57];
					SystemLog systemLog = new SystemLog("Update_Log.bin");
					string[] array = UsbUpgradeFile.UsbUpgrade_GetLogs();
					for (int i = 0; i < array.Length; i++)
					{
						systemLog.WriteLog(array[i]);
					}
					RegeditManager.SetUpdateFailInfo(updateFialInfo[0], updateFialInfo[1], updateFialInfo[2], updateFialInfo[3]);
				}
				UpdateTimerOutCnt = 0;
				updating = false;
				customButton_Confirm.Visible = true;
				break;
			case UpgradeState.UpgradeState:
				break;
			}
		}

		public void UpgradeHandler(byte[] command)
		{
			Invoke((Action)delegate
			{
				UpgradeDataHandler(command);
			});
		}

		private void customButton_Close_Click(object sender, EventArgs e)
		{
			exit();
		}

		private void customButton_Confirm_Click(object sender, EventArgs e)
		{
			exit();
		}

		private void FormUpdate_KeyDown(object sender, KeyEventArgs e)
		{
			if (e.KeyCode == Keys.Return)
			{
				if (customButton_Update.Visible)
				{
					customButton_Update_Click(null, null);
				}
				else
				{
					exit();
				}
			}
			else if (e.KeyCode == Keys.Escape)
			{
				exit();
			}
		}

		private void exit()
		{
			if (!updating)
			{
				UsbFinder.StopUsbChanged();
				CheckDevicesTimer = null;
				if (pollingThread != null)
				{
					pollingThread.Abort();
				}
				Close();
			}
		}

		public FormUpdate(DriveConfig.DriveParam drive, DriveConfig.DeviceParam device = null, bool repair = false)
		{
			InitializeComponent();
			driveParam = drive;
			ImageInit();
			formResize.Resize(this);
			LanguageFile.FormSetColor(this);
			label_UpdatingTips.ForeColor = driveParam.TipsClr;
			base.ShowInTaskbar = false;
			base.StartPosition = FormStartPosition.CenterParent;
			updating = false;
			finding = true;
			if (repair)
			{
				RegeditManager.GetUpdateFailInfo(out updateFialInfo);
				_ = updateFialInfo[0];
				for (int i = 0; i < driveParam.DeviceTotal; i++)
				{
					if (driveParam.DeviceParams[i].MID == updateFialInfo[3])
					{
						deviceParam = driveParam.DeviceParams[i];
						break;
					}
				}
			}
			else
			{
				deviceParam = device;
			}
			if (UpdateTimerOut == null)
			{
				UpdateTimerOut = new System.Windows.Forms.Timer();
				UpdateTimerOut.Interval = 1000;
				UpdateTimerOut.Tick += UpdateTimerOut_Tick;
			}
			if (CheckDevicesTimer == null)
			{
				CheckDevicesTimer = new System.Windows.Forms.Timer();
				CheckDevicesTimer.Interval = 300;
				CheckDevicesTimer.Tick += CheckDevicesTimer_Tick;
			}
			CheckDevicesTimer.Start();
			USBProcess_Init();
			pollingThread = new Thread(TogetherUpdateProcess);
		}

		private void TogetherUpdateProcess()
		{
			while (!dongleUpdateFinish || CheckNormalDongle() != 1)
			{
				Thread.Sleep(1000);
			}
			if (dongleUpdateFinish)
			{
				UpdateTimerOut.Enabled = false;
				UpdateTimerOutCnt = 0;
				if (CheckMouseCount() == 1)
				{
					UpdateMouse();
					while (!mouseUpdateFinish || DevicesInfo.Count != 2)
					{
						Thread.Sleep(200);
					}
					if (GetDongleRFID())
					{
						UpdateMouseRFID();
					}
				}
			}
			Update_Finish();
		}

		private void CheckDevicesTimer_Tick(object sender, EventArgs e)
		{
			if (updating)
			{
				return;
			}
			if (CheckDongleCount() == 1 && CheckMouseCount() == 1)
			{
				label_UpdatingTips.Text = LanguageFile.Dialogs[107];
				customButton_Update.Visible = true;
				return;
			}
			if (CheckDongleCount() > 1)
			{
				label_UpdatingTips.Text = LanguageFile.Dialogs[109];
			}
			else if (CheckMouseCount() > 1)
			{
				label_UpdatingTips.Text = LanguageFile.Dialogs[111];
			}
			else if (CheckDongleCount() == 0)
			{
				label_UpdatingTips.Text = LanguageFile.Dialogs[108];
			}
			else if (CheckMouseCount() == 0)
			{
				label_UpdatingTips.Text = LanguageFile.Dialogs[110];
			}
			customButton_Update.Visible = false;
		}

		private int CheckDongleCount()
		{
			int num = 0;
			string text = "";
			byte[] buffers = null;
			string[] array = null;
			List<string> list = null;
			CXFILE_TYPE cXFILE_TYPE = CXFILE_TYPE.Dongle;
			int cID = driveParam.CID;
			dongleBootDevice = new string[4][];
			if (deviceParam.DM != null)
			{
				text = deviceParam.DM;
				if (DeviceUpdateFile.HasDeviceUpdateFile((byte)cXFILE_TYPE, "", text, (byte)cID, (byte)deviceParam.MID, out buffers))
				{
					array = UsbFinder.FindBootDevices(buffers);
					dongleBuffs[0] = buffers;
					dongleBootDevice[0] = array;
				}
			}
			if (deviceParam.D2M != null)
			{
				text = deviceParam.D2M;
				if (DeviceUpdateFile.HasDeviceUpdateFile((byte)cXFILE_TYPE, "", text, (byte)cID, (byte)deviceParam.MID, out buffers))
				{
					array = UsbFinder.FindBootDevices(buffers);
					dongleBuffs[1] = buffers;
					dongleBootDevice[1] = array;
				}
			}
			if (deviceParam.D4M != null)
			{
				text = deviceParam.D4M;
				if (DeviceUpdateFile.HasDeviceUpdateFile((byte)cXFILE_TYPE, "", text, (byte)cID, (byte)deviceParam.MID, out buffers))
				{
					array = UsbFinder.FindBootDevices(buffers);
					dongleBuffs[2] = buffers;
					dongleBootDevice[2] = array;
				}
			}
			if (deviceParam.D8M != null)
			{
				text = deviceParam.D8M;
				if (DeviceUpdateFile.HasDeviceUpdateFile((byte)cXFILE_TYPE, "", text, (byte)cID, (byte)deviceParam.MID, out buffers))
				{
					array = UsbFinder.FindBootDevices(buffers);
					dongleBuffs[3] = buffers;
					dongleBootDevice[3] = array;
				}
			}
			list = new List<string>();
			list.Clear();
			for (int i = 0; i < DevicesInfo.Count; i++)
			{
				if (!DevicesInfo[i].isUSB)
				{
					list.Add(DevicesInfo[i].deviceString);
				}
			}
			num = list.Count;
			dongleBootDevices = 0;
			for (int j = 0; j < dongleBootDevice.Length; j++)
			{
				dongleBootDevices += ((dongleBootDevice[j] != null) ? dongleBootDevice[j].Length : 0);
			}
			return num + dongleBootDevices;
		}

		private int CheckNormalDongle()
		{
			int num = 0;
			for (int i = 0; i < DevicesInfo.Count; i++)
			{
				if (!DevicesInfo[i].isUSB)
				{
					num++;
				}
			}
			return num;
		}

		private bool CheckDongleVersion()
		{
			bool result = false;
			for (int i = 0; i < DevicesInfo.Count; i++)
			{
				if (DevicesInfo[i].isUSB)
				{
					continue;
				}
				string mcu = "";
				if (DevicesInfo[i].deviceInfo.DeviceType == 5)
				{
					dongleReportRate = 8;
					mcu = deviceParam.D8M;
				}
				else if (DevicesInfo[i].deviceInfo.DeviceType == 1)
				{
					dongleReportRate = 4;
					mcu = deviceParam.D4M;
				}
				else if (DevicesInfo[i].deviceInfo.DeviceType == 4)
				{
					dongleReportRate = 2;
					mcu = deviceParam.D2M;
				}
				else if (DevicesInfo[i].deviceInfo.DeviceType == 0)
				{
					dongleReportRate = 1;
					mcu = deviceParam.DM;
				}
				string currentVersion = DevicesInfo[i].DongleVersion;
				if (dongleReportRate >= 2)
				{
					int slaveVersion = 0;
					string text = "";
					if (UsbFinder.GetSlaveVersion(DevicesInfo[i].deviceString, out slaveVersion))
					{
						text = "v" + ValueConvert.IntToVersion(slaveVersion);
					}
					currentVersion = text;
				}
				return DeviceUpdateFile.HasDeviceUpdateFile(211, currentVersion, mcu, (byte)driveParam.CID, (byte)deviceParam.MID, out dongleBuff);
			}
			for (int j = 0; j < dongleBootDevice.Length; j++)
			{
				if (dongleBuffs[j] != null && dongleBootDevice[j].Length == 1)
				{
					dongleBuff = dongleBuffs[j];
					dongleReportRate = 1 << j;
					return true;
				}
			}
			return result;
		}

		private bool GetDongleRFID()
		{
			bool result = false;
			if (DevicesInfo.Count + dongleBootDevices + mouseBootDevice.Length == 2)
			{
				for (int i = 0; i < DevicesInfo.Count; i++)
				{
					if (!DevicesInfo[i].isUSB)
					{
						byte[] deviceOnLineWithAddress = UsbFinder.GetDeviceOnLineWithAddress(DevicesInfo[i].deviceString);
						rfid[0] = deviceOnLineWithAddress[9];
						rfid[1] = deviceOnLineWithAddress[8];
						rfid[2] = deviceOnLineWithAddress[7];
						result = true;
					}
				}
			}
			return result;
		}

		private bool UpdateDongle()
		{
			bool result = true;
			if (dongleNeedUpdate)
			{
				dongleUpdateFinish = false;
				Invoke((EventHandler)delegate
				{
					label_UpdatingTips.Text = LanguageFile.Dialogs[58];
					result = UsbFinder.UsbUpgrade_Start(dongleBuff, UpgradeTogetherHandler, 10000);
					finding = false;
					customButton_Confirm.Visible = false;
					SetProcessValue(0);
					label_UpdatingTips.Text = LanguageFile.Dialogs[58] + "：0%";
				});
				UpgradeFileHeader upgradeFileHeader = UsbUpgradeFile.ByteToStruct(dongleBuff);
				updateFialInfo = new List<byte>();
				updateFialInfo.Add(upgradeFileHeader.DeciveType);
				updateFialInfo.Add((byte)dongleReportRate);
				updateFialInfo.Add(upgradeFileHeader.Cid);
				updateFialInfo.Add(upgradeFileHeader.Mid);
				dongleVersion = "v" + ValueConvert.IntToVersion((int)upgradeFileHeader.version);
			}
			else
			{
				dongleUpdateFinish = true;
			}
			return result;
		}

		private int CheckMouseCount()
		{
			DeviceUpdateFile.HasDeviceUpdateFile((byte)210, "", deviceParam.MM, (byte)driveParam.CID, (byte)deviceParam.MID, out UpdateBuffer);
			mouseBootDevice = UsbFinder.FindBootDevices(UpdateBuffer);
			List<string> list = new List<string>();
			for (int i = 0; i < DevicesInfo.Count; i++)
			{
				if (DevicesInfo[i].isUSB)
				{
					list.Add(DevicesInfo[i].deviceString);
				}
			}
			return list.Count + mouseBootDevice.Length;
		}

		private bool CheckMouseVersion()
		{
			bool result = false;
			for (int i = 0; i < DevicesInfo.Count; i++)
			{
				if (DevicesInfo[i].isUSB)
				{
					return DeviceUpdateFile.HasDeviceUpdateFile(210, DevicesInfo[i].DongleVersion, deviceParam.MM, (byte)driveParam.CID, (byte)deviceParam.MID, out mouseBuff);
				}
			}
			if (mouseBootDevice.Length == 1)
			{
				return DeviceUpdateFile.HasDeviceUpdateFile(210, "", deviceParam.MM, (byte)driveParam.CID, (byte)deviceParam.MID, out mouseBuff);
			}
			return result;
		}

		private bool UpdateMouse()
		{
			bool result = true;
			if (mouseNeedUpdate)
			{
				mouseUpdateFinish = false;
				Invoke((EventHandler)delegate
				{
					label_UpdatingTips.Text = LanguageFile.Dialogs[58];
					result = UsbFinder.UsbUpgrade_Start(mouseBuff, UpgradeTogetherHandler, 10000);
					finding = false;
					customButton_Confirm.Visible = false;
					SetProcessValue(dongleNeedUpdate ? 50 : 0);
					label_UpdatingTips.Text = LanguageFile.Dialogs[58] + (dongleNeedUpdate ? "：50%" : "：0%");
				});
				UpgradeFileHeader upgradeFileHeader = UsbUpgradeFile.ByteToStruct(mouseBuff);
				updateFialInfo = new List<byte>();
				updateFialInfo.Add(upgradeFileHeader.DeciveType);
				updateFialInfo.Add(0);
				updateFialInfo.Add(upgradeFileHeader.Cid);
				updateFialInfo.Add(upgradeFileHeader.Mid);
				mouseVersion = "v" + ValueConvert.IntToVersion((int)upgradeFileHeader.version);
			}
			else
			{
				mouseUpdateFinish = true;
			}
			return result;
		}

		private void UpdateMouseRFID()
		{
			byte[] array = new byte[5]
			{
				rfid[0],
				rfid[1],
				rfid[2],
				0,
				0
			};
			if (dongleReportRate == 1)
			{
				array[4] = 0;
			}
			else if (dongleReportRate == 2 || dongleReportRate == 4)
			{
				array[4] = 1;
			}
			else if (dongleReportRate == 8)
			{
				array[4] = 2;
			}
			for (int i = 0; i < DevicesInfo.Count; i++)
			{
				if (DevicesInfo[i].isUSB)
				{
					UsbFinder.SetDongleIDToMouse(DevicesInfo[i].deviceString, array);
				}
			}
		}

		private void Update_Finish()
		{
			updating = false;
			Invoke((EventHandler)delegate
			{
				if (updateSuccess)
				{
					RegeditManager.ClearUpdateFailInfo();
					label_UpdatingTips.Text = LanguageFile.Dialogs[56];
				}
				else
				{
					RegeditManager.SetUpdateFailInfo(updateFialInfo[0], updateFialInfo[1], updateFialInfo[2], updateFialInfo[3]);
					label_UpdatingTips.Text = LanguageFile.Dialogs[57];
				}
				customButton_Cancel.Visible = true;
				customButton_Confirm.Visible = true;
				customButton_Confirm.Location = customButton_Update.Location;
			});
		}

		private void USBProcess_Init()
		{
			UsbFinder.StartUsbChanged(OnUsbChangedEvent, 600);
		}

		private void OnUsbChangedEvent(bool isPlug)
		{
			int interfaceid = driveParam.Interfaceid;
			int deviceid = driveParam.Deviceid;
			DevicesInfo.Clear();
			List<string> list = new List<string>();
			for (int i = 0; i < driveParam.M_PID.Count; i++)
			{
				list.Add(driveParam.M_PID[i]);
			}
			for (int j = 0; j < driveParam.D_PID.Count; j++)
			{
				list.Add(driveParam.D_PID[j]);
			}
			GetDeviceInfo(driveParam.VID, list, interfaceid, deviceid);
		}

		private void GetDeviceInfo(List<string> VID, List<string> PID, int interfaceId, int deviceId)
		{
			for (int i = 0; i < VID.Count; i++)
			{
				string text = VID[i];
				for (int j = 0; j < PID.Count; j++)
				{
					if (!(PID[j] != "0000"))
					{
						continue;
					}
					string[] array = UsbFinder.FindHidDevicesByDeviceId(text, PID[j], interfaceId, deviceId);
					for (int k = 0; k < array.Length; k++)
					{
						DeviceAllInfo deviceAllInfo = new DeviceAllInfo
						{
							deviceString = array[k],
							VID = text,
							PID = PID[j]
						};
						HIDD_ATTRIBUTES hidd_attributes = default(HIDD_ATTRIBUTES);
						UsbFinder.GetUsbDeviceAttribute(array[k], out hidd_attributes);
						int versionNumber = hidd_attributes.VersionNumber;
						deviceAllInfo.DongleVersion = "v" + ValueConvert.IntToVersion(versionNumber);
						deviceAllInfo.online = false;
						deviceAllInfo.deviceIndex = driveParam.DeviceTotal;
						if (GetDeviceInfo(ref deviceAllInfo) == 1)
						{
							DevicesInfo.Add(deviceAllInfo);
						}
					}
				}
			}
		}

		private int GetDeviceInfo(ref DeviceAllInfo deviceAllInfo)
		{
			int result = 0;
			int i = 0;
			string deviceString = deviceAllInfo.deviceString;
			DeviceInfo deviceInfo = default(DeviceInfo);
			for (; i < 10; i++)
			{
				if (deviceInfo.CID != 0)
				{
					break;
				}
				if (deviceInfo.MID != 0)
				{
					break;
				}
				UsbFinder.GetDeviceInfo(deviceString, out deviceInfo);
			}
			if (i < 10)
			{
				DeviceType deviceType = (DeviceType)deviceInfo.DeviceType;
				if (deviceType.ToString().Contains("Wireless"))
				{
					deviceAllInfo.isUSB = false;
				}
				else
				{
					deviceAllInfo.isUSB = true;
				}
				deviceAllInfo.deviceInfo = deviceInfo;
				if (deviceInfo.CID == driveParam.CID && deviceInfo.MID == deviceParam.MID)
				{
					result = 1;
				}
			}
			return result;
		}

		private void customButton_Update_Click(object sender, EventArgs e)
		{
			CheckDevicesTimer.Stop();
			dongleNeedUpdate = CheckDongleVersion();
			mouseNeedUpdate = CheckMouseVersion();
			if (dongleNeedUpdate || mouseNeedUpdate)
			{
				updating = true;
				customButton_Update.Visible = false;
				customButton_Cancel.Visible = false;
				if (UpdateDongle())
				{
					pollingThread.Start();
				}
			}
		}

		public void UpgradeTogetherHandler(byte[] command)
		{
			Invoke((Action)delegate
			{
				UpgradeTogetherDataHandler(command);
			});
		}

		private void UpgradeTogetherDataHandler(byte[] command)
		{
			int num = 1;
			if (dongleNeedUpdate && mouseNeedUpdate)
			{
				num = 2;
			}
			if (command[0] != 7)
			{
				return;
			}
			switch ((UpgradeState)command[1])
			{
			case UpgradeState.DownLoadFile:
			{
				int processValue = command[2] / num + (dongleNeedUpdate ? (dongleUpdateFinish ? 50 : 0) : 0);
				SetProcessValue(processValue);
				label_UpdatingTips.Text = LanguageFile.Dialogs[58] + "：" + processValue + "%";
				break;
			}
			case UpgradeState.UpgradeResult:
				if (command[2] == 1)
				{
					SetProcessValue(100 / num + (dongleNeedUpdate ? (dongleUpdateFinish ? 50 : 0) : 0));
					if (!dongleUpdateFinish)
					{
						dongleUpdateFinish = true;
						if (!mouseNeedUpdate)
						{
							updateSuccess = true;
						}
					}
					else if (!mouseUpdateFinish)
					{
						mouseUpdateFinish = true;
						updateSuccess = true;
					}
				}
				else
				{
					updateSuccess = false;
					SystemLog systemLog = new SystemLog("Update_Log.bin");
					string[] array = UsbUpgradeFile.UsbUpgrade_GetLogs();
					for (int i = 0; i < array.Length; i++)
					{
						systemLog.WriteLog(array[i]);
					}
					RegeditManager.SetUpdateFailInfo(updateFialInfo[0], updateFialInfo[1], updateFialInfo[2], updateFialInfo[3]);
				}
				UpdateTimerOutCnt = 0;
				UpdateTimerOut.Enabled = true;
				break;
			case UpgradeState.UpgradeState:
				break;
			}
		}

