			label_UpdateTips.Text = LanguageFile.Dialogs[(int)dialog];
			label_NewVerTips.Text = LanguageFile.Dialogs[92];
		}

		private bool CheckDongleUpdate()
		{
			CXFILE_TYPE cXFILE_TYPE = CXFILE_TYPE.Dongle;
			string text = "";
			bool flag = false;
			int num = 0;
			Dongle = new List<string>();
			byte[] buffers;
			if (FormMain.ConnectedDeviceInfo.isUSB)
			{
				if (deviceParam.D4M != null)
				{
					text = deviceParam.D4M;
					flag = DeviceUpdateFile.HasDeviceUpdateFile((byte)cXFILE_TYPE, "", text, (byte)CID, (byte)deviceParam.MID, out buffers);
					boot4KDongle = UsbFinder.FindBootDevices(buffers);
				}
				if (deviceParam.D2M != null)
				{
					text = deviceParam.D2M;
					flag = DeviceUpdateFile.HasDeviceUpdateFile((byte)cXFILE_TYPE, "", text, (byte)CID, (byte)deviceParam.MID, out buffers);
					boot2KDongle = UsbFinder.FindBootDevices(buffers);
				}
				if (deviceParam.DM != null)
				{
					text = deviceParam.DM;
					flag = DeviceUpdateFile.HasDeviceUpdateFile((byte)cXFILE_TYPE, "", text, (byte)CID, (byte)deviceParam.MID, out buffers);
					boot1KDongle = UsbFinder.FindBootDevices(buffers);
				}
				Dongle = new List<string>();
				Dongle.Clear();
				for (int i = 0; i < FormMain.AllDeviceInfoList.Count; i++)
				{
					if (!FormMain.AllDeviceInfoList[i].isUSB)
					{
						Dongle.Add(FormMain.AllDeviceInfoList[i].deviceString);
					}
				}
			}
			else
			{
				if (FormMain.SelectedDeviceInfo.deviceInfo.DeviceType == 5)
				{
					reportRate = 8;
				}
				else if (FormMain.SelectedDeviceInfo.deviceInfo.DeviceType == 1)
				{
					reportRate = 4;
				}
				else if (FormMain.SelectedDeviceInfo.deviceInfo.DeviceType == 4)
				{
					reportRate = 2;
				}
				else if (FormMain.SelectedDeviceInfo.deviceInfo.DeviceType == 0)
				{
					reportRate = 1;
				}
				if (reportRate == 8)
				{
					text = deviceParam.D8M;
					flag = DeviceUpdateFile.HasDeviceUpdateFile((byte)cXFILE_TYPE, "", text, (byte)CID, (byte)deviceParam.MID, out buffers);
					boot8KDongle = UsbFinder.FindBootDevices(buffers);
				}
				else if (reportRate == 4)
				{
					text = deviceParam.D4M;
					flag = DeviceUpdateFile.HasDeviceUpdateFile((byte)cXFILE_TYPE, "", text, (byte)CID, (byte)deviceParam.MID, out buffers);
					boot4KDongle = UsbFinder.FindBootDevices(buffers);
				}
				else if (reportRate == 2)
				{
					text = deviceParam.D2M;
					flag = DeviceUpdateFile.HasDeviceUpdateFile((byte)cXFILE_TYPE, "", text, (byte)CID, (byte)deviceParam.MID, out buffers);
					boot2KDongle = UsbFinder.FindBootDevices(buffers);
				}
				else
				{
					text = deviceParam.DM;
					flag = DeviceUpdateFile.HasDeviceUpdateFile((byte)cXFILE_TYPE, "", text, (byte)CID, (byte)deviceParam.MID, out buffers);
					boot1KDongle = UsbFinder.FindBootDevices(buffers);
				}
				for (int j = 0; j < FormMain.AllDeviceInfoList.Count; j++)
				{
					if (!FormMain.AllDeviceInfoList[j].isUSB && FormMain.AllDeviceInfoList[j].deviceString == FormMain.SelectedDeviceInfo.deviceString)
					{
						Dongle.Add(FormMain.SelectedDeviceInfo.deviceString);
					}
				}
			}
			num = Dongle.Count + ((boot1KDongle != null) ? boot1KDongle.Length : 0) + ((boot2KDongle != null) ? boot2KDongle.Length : 0) + ((boot4KDongle != null) ? boot4KDongle.Length : 0) + ((boot8KDongle != null) ? boot8KDongle.Length : 0);
			if (num == 1)
			{
				flag = false;
				if (boot1KDongle != null && boot1KDongle.Length == 1)
				{
					flag = DeviceUpdateFile.HasDeviceUpdateFile((byte)cXFILE_TYPE, "", deviceParam.DM, (byte)CID, (byte)deviceParam.MID, out UpdateBuffer);
					flag = true;
					reportRate = 1;
				}
				if (boot2KDongle != null && !flag && boot2KDongle.Length == 1)
				{
					flag = DeviceUpdateFile.HasDeviceUpdateFile((byte)cXFILE_TYPE, "", deviceParam.D2M, (byte)CID, (byte)deviceParam.MID, out UpdateBuffer);
					flag = true;
					reportRate = 2;
				}
				if (boot4KDongle != null && !flag && boot4KDongle.Length == 1)
				{
					flag = DeviceUpdateFile.HasDeviceUpdateFile((byte)cXFILE_TYPE, "", deviceParam.D4M, (byte)CID, (byte)deviceParam.MID, out UpdateBuffer);
					flag = true;
					reportRate = 4;
				}
				if (boot8KDongle != null && !flag && boot8KDongle.Length == 1)
				{
					flag = DeviceUpdateFile.HasDeviceUpdateFile((byte)cXFILE_TYPE, "", deviceParam.D8M, (byte)CID, (byte)deviceParam.MID, out UpdateBuffer);
					flag = true;
					reportRate = 8;
				}
				if (!flag)
				{
					if (FormMain.ConnectedDeviceInfo.isUSB)
					{
						for (int k = 0; k < FormMain.AllDeviceInfoList.Count; k++)
						{
							if (!FormMain.AllDeviceInfoList[k].isUSB)
							{
								if (FormMain.AllDeviceInfoList[k].deviceInfo.DeviceType == 5)
								{
									reportRate = 8;
								}
								else if (FormMain.AllDeviceInfoList[k].deviceInfo.DeviceType == 1)
								{
									reportRate = 4;
								}
								else if (FormMain.AllDeviceInfoList[k].deviceInfo.DeviceType == 4)
								{
									reportRate = 2;
								}
								else if (FormMain.AllDeviceInfoList[k].deviceInfo.DeviceType == 0)
								{
									reportRate = 1;
								}
								break;
							}
						}
					}
					if (reportRate == 8)
					{
						int slaveVersion = 0;
						string currentVersion = "";
						if (UsbFinder.GetSlaveVersion(Dongle[0], out slaveVersion))
						{
							currentVersion = "v" + ValueConvert.IntToVersion(slaveVersion);
						}
						flag = DeviceUpdateFile.HasDeviceUpdateFile((byte)cXFILE_TYPE, currentVersion, deviceParam.D8M, (byte)CID, (byte)deviceParam.MID, out UpdateBuffer);
					}
					else if (reportRate == 4)
					{
						int slaveVersion2 = 0;
						string currentVersion2 = "";
						if (UsbFinder.GetSlaveVersion(Dongle[0], out slaveVersion2))
						{
							currentVersion2 = "v" + ValueConvert.IntToVersion(slaveVersion2);
						}
						flag = DeviceUpdateFile.HasDeviceUpdateFile((byte)cXFILE_TYPE, currentVersion2, deviceParam.D4M, (byte)CID, (byte)deviceParam.MID, out UpdateBuffer);
					}
					else if (reportRate == 2)
					{
						int slaveVersion3 = 0;
						string currentVersion3 = "";
						if (UsbFinder.GetSlaveVersion(Dongle[0], out slaveVersion3))
						{
							currentVersion3 = "v" + ValueConvert.IntToVersion(slaveVersion3);
						}
						flag = DeviceUpdateFile.HasDeviceUpdateFile((byte)cXFILE_TYPE, currentVersion3, deviceParam.D2M, (byte)CID, (byte)deviceParam.MID, out UpdateBuffer);
					}
					else
					{
						flag = DeviceUpdateFile.HasDeviceUpdateFile((byte)cXFILE_TYPE, label_DongleVersionValue.Text, deviceParam.DM, (byte)CID, (byte)deviceParam.MID, out UpdateBuffer);
					}
					if (!flag)
					{
						pictureBox_Tips.Visible = false;
						label_UpdateTips.Visible = false;
						dongleLastVersion = true;
						customButton_DongleUpdate.Text = LanguageFile.Dialogs[54];
					}
				}
			}
			else
			{
				flag = false;
				if (num == 0)
				{
					dialog = DialogEnum.NoDevice;
				}
				else
				{
					dialog = DialogEnum.MultiOnline;
				}
				if (!flag)
				{
					pictureBox_Tips.Visible = true;
					label_UpdateTips.Visible = true;
					pictureBox_Tips.Location = new Point(pictureBox_Tips.Left, customButton_DongleUpdate.Top + (customButton_DongleUpdate.Height - pictureBox_Tips.Height) / 2);
					label_UpdateTips.Location = new Point(pictureBox_Tips.Right + 5, pictureBox_Tips.Top);
					label_UpdateTips.Text = LanguageFile.Dialogs[(int)dialog];
				}
			}
			if (needUpdateAnother && !flag)
			{
				new FormDialog(LanguageFile.Dialogs[(int)dialog]).ShowDialog();
			}
			needUpdateAnother = false;
			return flag;
		}

		private void customButton_DongleUpdate_Click(object sender, EventArgs e)
		{
			FormMain.OnlineCheckCount = 0;
			if (!CheckDongleUpdate())
			{
				return;
			}
			updating = true;
			DeviceUpdating?.Invoke(this, updating);
			pictureBox_Tips.Visible = false;
			label_UpdateTips.Visible = false;
			FormUpdate formUpdate = new FormUpdate(UpdateBuffer, (byte)reportRate);
			formUpdate.ShowDialog();
			updating = false;
			DeviceUpdating?.Invoke(this, updating);
			if (formUpdate.updateSuccess)
			{
				UpgradeFileHeader upgradeFileHeader = UsbUpgradeFile.ByteToStruct(UpdateBuffer);
				label_DongleVersionValue.Text = "v" + ValueConvert.IntToVersion((int)upgradeFileHeader.version);
				dongleLastVersion = true;
				customButton_DongleUpdate.Text = LanguageFile.Dialogs[54];
				dongleHaveNewVer = false;
				customButton_DongleUpdate.NormalImage = new Bitmap(AppDomain.CurrentDomain.BaseDirectory + "\\res\\7General\\ok_nr.png");
				customButton_DongleUpdate.MouseDownImage = new Bitmap(AppDomain.CurrentDomain.BaseDirectory + "\\res\\7General\\ok_down.png");
				customButton_DongleUpdate.MouseEnterImage = new Bitmap(AppDomain.CurrentDomain.BaseDirectory + "\\res\\7General\\ok_enter.png");
				if (mouseHaveNewVer)
				{
					needUpdateAnother = true;
					customButton_MouseUpdate_Click(null, null);
				}
			}
			else
			{
				label_DongleVersionValue.Text = "";
				DeviceUpdateFail?.Invoke(this);
			}
		}

		private bool CheckMouseUpdate()
		{
			CXFILE_TYPE cXFILE_TYPE = CXFILE_TYPE.Mouse;
			bool flag = false;
			flag = DeviceUpdateFile.HasDeviceUpdateFile((byte)cXFILE_TYPE, label_MouseVersionValue.Text, deviceParam.MM, (byte)CID, (byte)deviceParam.MID, out UpdateBuffer);
			string[] array = UsbFinder.FindBootDevices(UpdateBuffer);
			List<string> list = new List<string>();
			for (int i = 0; i < FormMain.AllDeviceInfoList.Count; i++)
			{
				if (FormMain.AllDeviceInfoList[i].isUSB)
				{
					list.Add(FormMain.AllDeviceInfoList[i].deviceString);
				}
			}
			for (int j = 0; j < array.Length; j++)
			{
				list.Add(array[j]);
			}
			if (list.Count == 1 || !flag)
			{
				flag = DeviceUpdateFile.HasDeviceUpdateFile((byte)cXFILE_TYPE, label_MouseVersionValue.Text, deviceParam.MM, (byte)CID, (byte)deviceParam.MID, out UpdateBuffer);
				if (!flag)
				{
					pictureBox_Tips.Visible = false;
					label_UpdateTips.Visible = false;
					mouseLastVersion = true;
					customButton_MouseUpdate.Text = LanguageFile.Dialogs[54];
				}
			}
			else
			{
				flag = false;
				if (list.Count == 0)
				{
					dialog = DialogEnum.OnlyWired;
				}
				else
				{
					dialog = DialogEnum.MultiOnline;
				}
				pictureBox_Tips.Visible = true;
				label_UpdateTips.Visible = true;
				pictureBox_Tips.Location = new Point(pictureBox_Tips.Left, customButton_MouseUpdate.Top + (customButton_MouseUpdate.Height - pictureBox_Tips.Height) / 2);
				label_UpdateTips.Location = new Point(pictureBox_Tips.Right + 5, pictureBox_Tips.Top);
				label_UpdateTips.Text = LanguageFile.Dialogs[(int)dialog];
			}
			if (needUpdateAnother && !flag)
			{
				new FormDialog(LanguageFile.Dialogs[(int)dialog]).ShowDialog();
			}
			needUpdateAnother = false;
			return flag;
		}

		private void customButton_MouseUpdate_Click(object sender, EventArgs e)
		{
			FormMain.OnlineCheckCount = 0;
			if (!CheckMouseUpdate())
			{
				return;
			}
			updating = true;
			DeviceUpdating?.Invoke(this, updating);
			pictureBox_Tips.Visible = false;
			label_UpdateTips.Visible = false;
			FormUpdate formUpdate = new FormUpdate(UpdateBuffer, 0);
			formUpdate.ShowDialog();
			updating = false;
			DeviceUpdating?.Invoke(this, updating);
			if (formUpdate.updateSuccess)
			{
				UpgradeFileHeader upgradeFileHeader = UsbUpgradeFile.ByteToStruct(UpdateBuffer);
				label_MouseVersionValue.Text = "v" + ValueConvert.IntToVersion((int)upgradeFileHeader.version);
				RegeditManager.SetMouseVersion((byte)CID, (byte)deviceParam.MID, label_MouseVersionValue.Text);
				mouseLastVersion = true;
				customButton_MouseUpdate.Text = LanguageFile.Dialogs[54];
				mouseHaveNewVer = false;
				customButton_MouseUpdate.NormalImage = new Bitmap(AppDomain.CurrentDomain.BaseDirectory + "\\res\\7General\\ok_nr.png");
				customButton_MouseUpdate.MouseDownImage = new Bitmap(AppDomain.CurrentDomain.BaseDirectory + "\\res\\7General\\ok_down.png");
				customButton_MouseUpdate.MouseEnterImage = new Bitmap(AppDomain.CurrentDomain.BaseDirectory + "\\res\\7General\\ok_enter.png");
				if (dongleHaveNewVer)
				{
					needUpdateAnother = true;
					customButton_DongleUpdate_Click(null, null);
				}
			}
			else
			{
				label_DongleVersionValue.Text = "";
				DeviceUpdateFail?.Invoke(this);
			}
		}

		private void customButton_Update_Click(object sender, EventArgs e)
		{
			FormMain.OnlineCheckCount = 0;
			if (!dongleHaveNewVer && !mouseHaveNewVer && !(label_DongleVersionValue.Text == "") && !(label_MouseVersionValue.Text == ""))
			{
				return;
			}
			updating = true;
			DeviceUpdating?.Invoke(this, updating);
			FormUpdate formUpdate = new FormUpdate(FormMain.driveParam, FormMain.deviceParam);
			formUpdate.ShowDialog();
			updating = false;
			DeviceUpdating?.Invoke(this, updating);
			if (formUpdate.updateSuccess)
			{
				dongleHaveNewVer = false;
				mouseHaveNewVer = false;
				if (formUpdate.dongleNeedUpdate)
				{
					label_DongleVersionValue.Text = formUpdate.dongleVersion;
				}
				if (formUpdate.mouseNeedUpdate)
				{
					label_MouseVersionValue.Text = formUpdate.mouseVersion;
				}
				customButton_Update.Text = LanguageFile.Dialogs[54];
				customButton_Update.NormalImage = new Bitmap(AppDomain.CurrentDomain.BaseDirectory + "\\res\\7General\\ok_nr.png");
				customButton_Update.MouseDownImage = new Bitmap(AppDomain.CurrentDomain.BaseDirectory + "\\res\\7General\\ok_down.png");
				customButton_Update.MouseEnterImage = new Bitmap(AppDomain.CurrentDomain.BaseDirectory + "\\res\\7General\\ok_enter.png");
			}
		}

