	public class UC_DongleLED : UserControl
	{
		private bool updatingUI;

		private IContainer components;

		private Label label_OnlyBattery;

		private Label label_BatteryState;

		private Label label_ConnectionState;

		private Panel panel_Dongle4KLED;

		private CustomRadioButton customRadioButton_OnlyBattery;

		private CustomRadioButton customRadioButton_ConnectionState;

		private CustomRadioButton customRadioButton_BatteryState;

		private Label label_DongleLED;

		private PictureBox pictureBox_Title;

		public int DongleLed
		{
			get
			{
				return 0;
			}
			set
			{
				updatingUI = true;
				foreach (Control control in panel_Dongle4KLED.Controls)
				{
					if (control is CustomRadioButton)
					{
						CustomRadioButton customRadioButton = (CustomRadioButton)control;
						if (int.Parse(customRadioButton.Tag.ToString()) == value)
						{
							customRadioButton.Checked = true;
						}
					}
				}
				updatingUI = false;
			}
		}

		public UC_DongleLED()
		{
			InitializeComponent();
			LanguageChange();
			foreach (Control control in panel_Dongle4KLED.Controls)
			{
				if (control is CustomRadioButton)
				{
					((CustomRadioButton)control).CheckedChanged += Button_CheckedChanged;
				}
			}
		}

		private void Button_CheckedChanged(object sender, EventArgs e)
		{
			CustomRadioButton customRadioButton = (CustomRadioButton)sender;
			if (customRadioButton.Checked && !updatingUI && FormMain.GetDeviceOnlineFlag())
			{
				DongleRGB dongleRGB = new DongleRGB
				{
					mode = byte.Parse(customRadioButton.Tag.ToString())
				};
				UsbServer.Set4KDongleRGB(ref dongleRGB);
			}
		}

		public void LanguageChange()
		{
			label_DongleLED.Text = LanguageFile.Dialogs[77];
			label_ConnectionState.Text = LanguageFile.Dialogs[78];
			label_BatteryState.Text = LanguageFile.Dialogs[79];
			label_OnlyBattery.Text = LanguageFile.Dialogs[80];
		}

