	public class UC_Light : UserControl
	{
		private bool updateUI;

		private bool init;

		private IContainer components;

		private PictureBox pictureBox_Title;

		private Label label_SleepMode;

		private CustomComboBox customComboBox_PowerSaveTime;

		private Label label_MouseSleepTime;

		public UC_Light()
		{
			InitializeComponent();
			LanguageChange();
		}

		public void UI_Init()
		{
			CustomComboBox customComboBox = customComboBox_PowerSaveTime;
			Color unselectItemColor = (customComboBox_PowerSaveTime.BackColor = FormMain.driveParam.CbbBgClr);
			customComboBox.UnselectItemColor = unselectItemColor;
			customComboBox_PowerSaveTime.SelectItemColor = FormMain.driveParam.CbbItemClr;
			customComboBox_PowerSaveTime.ForeColor = FormMain.driveParam.CbbForeClr;
			customComboBox_PowerSaveTime.ArrowImageNoraml = ResourcesFile.GetComboxBoxBitmap();
			if (init)
			{
				return;
			}
			for (int i = 0; i < LanguageFile.ComboBoxStructs.Count; i++)
			{
				if (customComboBox_PowerSaveTime.Name == LanguageFile.ComboBoxStructs[i].Name)
				{
					customComboBox_PowerSaveTime.Item.Clear();
					for (int j = 0; j < LanguageFile.ComboBoxStructs[i].Items.Count; j++)
					{
						customComboBox_PowerSaveTime.Item.Add(LanguageFile.ComboBoxStructs[i].Items[j]);
					}
					break;
				}
			}
			int num = 0;
			for (int k = 0; k < LanguageFile.LabelStructs.Count; k++)
			{
				if (label_SleepMode.Name == LanguageFile.LabelStructs[k].Name)
				{
					label_SleepMode.Text = LanguageFile.LabelStructs[k].Text;
					num++;
				}
				if (label_MouseSleepTime.Name == LanguageFile.LabelStructs[k].Name)
				{
					label_MouseSleepTime.Text = LanguageFile.LabelStructs[k].Text;
					num++;
				}
				if (num == 3)
				{
					break;
				}
			}
			string[] array = FormMain.deviceParam.LightUI.Split(',');
			int[] array2 = new int[array.Length];
			for (int l = 0; l < array.Length; l++)
			{
				array2[l] = Convert.ToInt32(array[l]);
			}
			updateUI = true;
			customComboBox_PowerSaveTime.SelectIndex = ValueConvert.ValueToComboxIndex(customComboBox_PowerSaveTime, array2[4]);
			updateUI = false;
			init = true;
		}

		public void Update_PowerSaveTime(int value)
		{
			updateUI = true;
			customComboBox_PowerSaveTime.SelectIndex = ValueConvert.ValueToComboxIndex(customComboBox_PowerSaveTime, value);
			updateUI = false;
		}

		private void customComboBox_PowerSaveTime_OnSelectedIndexChanged(object sender, EventArgs e)
		{
			if (!updateUI && FormMain.GetDeviceOnlineFlag())
			{
				FormMain.gFlashDataMap.mouseConfig.allLedOffTime = (byte)ValueConvert.ComboxIndexToValue(customComboBox_PowerSaveTime);
				DataParser.Update(FormMain.gFlashDataMap);
			}
		}

