namespace Mouse_Drive_Beta.SkinFormLib
{
	public class FormResize
	{
		private const int HORZRES = 8;

		private const int VERTRES = 10;

		private const int LOGPIXELSX = 88;

		private const int LOGPIXELSY = 90;

		private const int DESKTOPVERTRES = 117;

		private const int DESKTOPHORZRES = 118;

		private const int DEFAULTDPI = 96;

		[DllImport("user32.dll")]
		private static extern IntPtr GetDC(IntPtr ptr);

		[DllImport("gdi32.dll")]
		private static extern int GetDeviceCaps(IntPtr hdc, int nIndex);

		[DllImport("user32.dll")]
		private static extern IntPtr ReleaseDC(IntPtr hWnd, IntPtr hDc);

		public void Resize(Form form)
		{
			IntPtr dC = GetDC(IntPtr.Zero);
			int deviceCaps = GetDeviceCaps(dC, 88);
			deviceCaps = GetDeviceCaps(dC, 90);
			ReleaseDC(IntPtr.Zero, dC);
			form.Width = form.Width * deviceCaps / 96;
			form.Height = form.Height * deviceCaps / 96;
			Resize(form, deviceCaps);
		}

		private static void Resize(Control father, int scale)
		{
			foreach (Control control in father.Controls)
			{
				control.Width = control.Width * scale / 96;
				control.Height = control.Height * scale / 96;
				control.Location = new Point(control.Location.X * scale / 96, control.Location.Y * scale / 96);
				if (!(control is CustomComboBox) && control.HasChildren)
				{
					Resize(control, scale);
				}
			}
		}

		public static void ResizeInit(Control control)
		{
			IntPtr dC = GetDC(IntPtr.Zero);
			int deviceCaps = GetDeviceCaps(dC, 88);
			deviceCaps = GetDeviceCaps(dC, 90);
			ReleaseDC(IntPtr.Zero, dC);
			Resize(control, deviceCaps);
		}

		public static int GetDpi()
		{
			IntPtr dC = GetDC(IntPtr.Zero);
			GetDeviceCaps(dC, 88);
			int deviceCaps = GetDeviceCaps(dC, 90);
			ReleaseDC(IntPtr.Zero, dC);
			return deviceCaps;
		}
	}
}
