		private static void ForeachSetControlBitmap(Control father, GeneralBitmap resourcesBitmap)
		{
			foreach (Control control in father.Controls)
			{
				if (control is PictureBox)
				{
					PictureBox pictureBox = (PictureBox)control;
					if (control.Name.Contains("Title"))
					{
						pictureBox.BackgroundImage = resourcesBitmap.PictureTitle;
					}
					else if (control.Name.Contains("Tips"))
					{
						pictureBox.BackgroundImage = resourcesBitmap.PictureTips;
					}
					else if (control.Name.Contains("WinMouse"))
					{
						pictureBox.BackgroundImage = resourcesBitmap.PictureWinMouse;
					}
				}
				else if (control is CustomRadioButton)
				{
					CustomRadioButton obj = (CustomRadioButton)control;
					obj.CheckImage = resourcesBitmap.RadioBtnCheck;
					obj.UncheckImage = resourcesBitmap.RadioBtnUncheck;
				}
				else if (control is CustomCheckBox)
				{
					CustomCheckBox obj2 = (CustomCheckBox)control;
					obj2.CheckImage = resourcesBitmap.CheckBoxCheck;
					obj2.UncheckImage = resourcesBitmap.CheckBoxUncheck;
				}
				else if (control is CustomButton)
				{
					CustomButton obj3 = (CustomButton)control;
					obj3.NormalImage = resourcesBitmap.BtnOKNr;
					obj3.MouseEnterImage = resourcesBitmap.BtnOKEnter;
					obj3.MouseDownImage = resourcesBitmap.BtnOKDown;
				}
				else if (!(control is CustomComboBox) && control.HasChildren)
				{
					SetControlBitmap(control);
				}
			}
		}

		public static void SetControlBitmap(Control father)
		{
