	public class RunBoot
	{
		private string systemStartPath => Environment.GetFolderPath(Environment.SpecialFolder.Startup);

		private string appAllPath => Process.GetCurrentProcess().MainModule.FileName;

		private string desktopPath => Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory);

		public void SetMeAutoStart(bool onOff = true)
		{
			if (onOff)
			{
				List<string> quickFromFolder = GetQuickFromFolder(systemStartPath, appAllPath);
				if (quickFromFolder.Count >= 2)
				{
					for (int i = 1; i < quickFromFolder.Count; i++)
					{
						DeleteFile(quickFromFolder[i]);
					}
				}
				else if (quickFromFolder.Count < 1)
				{
					try
					{
						CreateShortcut(systemStartPath, FormMain.driveParam.DriveName, appAllPath, 1, "", AppDomain.CurrentDomain.BaseDirectory + "\\res\\logo.ico");
						return;
					}
					catch (Exception ex)
					{
						_ = ex.Message;
						return;
					}
				}
				return;
			}
			List<string> quickFromFolder2 = GetQuickFromFolder(systemStartPath, appAllPath);
			if (quickFromFolder2.Count > 0)
			{
				for (int j = 0; j < quickFromFolder2.Count; j++)
				{
					DeleteFile(quickFromFolder2[j]);
				}
			}
		}

		private bool CreateShortcut(string directory, string shortcutName, string targetPath, int style, string description = null, string iconLocation = null)
		{
			try
			{
				if (!Directory.Exists(directory))
				{
					Directory.CreateDirectory(directory);
				}
				string pathLink = Path.Combine(directory, $"{shortcutName}.lnk");
				WshShell wshShell = (WshShell)Activator.CreateInstance(Marshal.GetTypeFromCLSID(new Guid("72C24DD5-D70A-438B-8A42-98424B88AFB8")));
				IWshShortcut obj = (IWshShortcut)(dynamic)wshShell.CreateShortcut(pathLink);
				obj.TargetPath = targetPath;
				obj.WorkingDirectory = Path.GetDirectoryName(targetPath);
				obj.WindowStyle = style;
				obj.Description = description;
				obj.IconLocation = (string.IsNullOrWhiteSpace(iconLocation) ? targetPath : iconLocation);
				obj.Save();
				return true;
			}
			catch (Exception ex)
			{
				_ = ex.Message;
			}
			return false;
		}

		public static List<string> GetQuickFromFolder(string directory, string targetPath)
		{
			List<string> list = new List<string>();
			list.Clear();
			try
			{
				string[] files = Directory.GetFiles(directory, "*.lnk");
				if (files == null || files.Length < 1)
				{
					return list;
				}
				for (int i = 0; i < files.Length; i++)
				{
					if (GetAppPathFromQuick(files[i]) == targetPath)
					{
						list.Add(files[i]);
					}
				}
			}
			catch (Exception ex)
			{
				_ = ex.Message;
			}
			return list;
		}

		public static string GetAppPathFromQuick(string shortcutPath)
		{
			if (File.Exists(shortcutPath))
			{
				WshShell wshShell = (WshShell)Activator.CreateInstance(Marshal.GetTypeFromCLSID(new Guid("72C24DD5-D70A-438B-8A42-98424B88AFB8")));
				return ((IWshShortcut)(dynamic)wshShell.CreateShortcut(shortcutPath)).TargetPath;
			}
			return "";
		}

		private void DeleteFile(string path)
		{
			if (File.GetAttributes(path) == FileAttributes.Directory)
			{
				Directory.Delete(path, recursive: true);
			}
			else
			{
				File.Delete(path);
			}
		}

		public void CreateDesktopQuick(string desktopPath = "", string quickName = "", string appPath = "")
		{
			if (GetQuickFromFolder(desktopPath, appPath).Count < 1)
			{
				CreateShortcut(desktopPath, quickName, appPath, 1, "");
			}
		}
	}
	public class SensorDPIFile
	{
		public List<SensorDPI> SensorDPIList = new List<SensorDPI>();

		public static void GetSensorDPI(ref SensorDPI sensorDPI)
		{
			string path = Convert.ToString(AppDomain.CurrentDomain.BaseDirectory) + "driver_sensor.h";
			new StreamReader(File.OpenRead(path));
			string[] array = File.ReadAllLines(path);
			sensorDPI.Discord = false;
			sensorDPI.DPIList = new List<int>();
			sensorDPI.DPIList.Clear();
			sensorDPI.DPIValueList = new List<int>();
			sensorDPI.DPIValueList.Clear();
			int num = sensorDPI.Min[0];
			string type = sensorDPI.Type;
			for (int i = 0; i < array.Length; i++)
			{
				string value = "SENSOR_" + type + "_DPI_" + num;
				if (!array[i].Contains(value))
				{
					continue;
				}
				string[] array2 = array[i].Split(' ', '\t');
				for (int j = 0; j < array2.Length; j++)
				{
					int item = 0;
					bool flag = false;
					try
					{
						item = ValueConvert.StringToInt(array2[j]);
						flag = true;
					}
					catch
					{
					}
					if (flag)
					{
						sensorDPI.DPIList.Add(num);
						sensorDPI.DPIValueList.Add(item);
						num += sensorDPI.Step[0];
						sensorDPI.Discord = true;
						break;
					}
				}
			}
		}

		private static string SupportSensorSetting(string setting)
		{
			string result = null;
			string path = Convert.ToString(AppDomain.CurrentDomain.BaseDirectory) + "driver_sensor.h";
			File.OpenRead(path);
			string[] array = File.ReadAllLines(path);
			for (int i = 0; i < array.Length; i++)
			{
				if (array[i].Contains(setting))
				{
					result = array[i];
					result = result.Replace("#define", "");
				}
			}
			return result;
		}

		public static bool SupportLODCal(string sensor)
		{
			bool result = false;
			if (SupportSensorSetting("SUPPORT_LOD_CAL").Contains(sensor))
			{
				result = true;
			}
			return result;
		}

		public static bool SupportSensorModeSel(string sensor)
		{
			bool result = false;
			if (SupportSensorSetting("SUPPORT_SENSOR_MODE_SEL").Contains(sensor))
			{
				result = true;
			}
			return result;
		}

		public static bool SupportRipple(string sensor)
		{
			bool result = false;
			if (SupportSensorSetting("SUPPORT_RIPPLE").Contains(sensor))
			{
				result = true;
			}
			return result;
		}

		public static bool SupportFixline(string sensor)
		{
			bool result = false;
			if (SupportSensorSetting("SUPPORT_FIXLINE").Contains(sensor))
			{
				result = true;
			}
			return result;
		}

		public static bool SupportMotionSync(string sensor)
		{
			bool result = false;
			if (SupportSensorSetting("SUPPORT_MOTION_SYNC").Contains(sensor))
