						gFlashDataMap.macroKey[i].name[j] = macroKeyAndCycle.macroKey.name[j];
					}
					gFlashDataMap.macroKey[i].contextCount = macroKeyAndCycle.macroKey.contextCount;
					for (int k = 0; k < macroKeyAndCycle.macroKey.contextCount; k++)
