	internal class DropDownBoxMessager : IMessageFilter
	{
		private const int WM_LBUTTONDOWN = 513;

		private const int WM_LBUTTONUP = 514;

		private const int WM_RBUTTONDOWN = 516;

		private const int WM_RBUTTONUP = 517;

		private const int WM_MBUTTONDOWN = 519;

		private const int WM_MBUTTONUP = 520;

		private const int WM_XBUTTONDOWN = 523;

		private const int WM_XBUTTONUP = 524;

		private CustomKeyFunction windDropDownBox;

		public DropDownBoxMessager(CustomKeyFunction _windDropDownBox)
		{
			windDropDownBox = _windDropDownBox;
		}

		public bool PreFilterMessage(ref Message m)
		{
			if (m.Msg == 514 && !windDropDownBox.isInClientRect() && !windDropDownBox.isDilog)
			{
				windDropDownBox.HideActiveWindows();
			}
			return false;
		}
	}
	public class CustomSetting : UserControl
	{
		public delegate void ExitPairingEventHandler(object sender);

		public delegate void LanguageChangeEventHandler(object sender, CustomEventArgs e);

		public delegate void DeviceUpdateFailEventHandler(object sender);

		public delegate void UpdateFinishEventHandler(object sender);

		private List<Point> ControlsPoints = new List<Point>();

		private List<int> LockPointIndexs = new List<int>();

		public bool updating;

		public bool pairing;

		private int lockControlCount;

		private bool addLongDistance;

		private bool addDongleRGB;

		private LanguageFile languageFile;

		private UC_Language uc_Language;

		private UC_DeviceUpdate uc_DeviceUpdate;

		private UC_Pair uc_Pair;

		private UC_Light uc_Light;

		private UC_System uc_System;

		private UC_Advanced uc_Advanced;

		private UC_Web uc_Web;

		private bool longDistance;

		private int powerSaveTime;

		private IContainer components;

		private Panel panel1;

		private Label label_DriveVersionValue;

		private Label label_DriveVersion;

		private CustomScrollBar customScrollBar1;

		public bool LongDistance
		{
			get
			{
				return longDistance;
			}
			set
			{
				longDistance = value;
				if (uc_Advanced != null)
				{
					uc_Advanced.UpdateLongDistance(longDistance);
				}
			}
		}

		public string DongleVersion
		{
			get
			{
				return "";
			}
			set
			{
				if (uc_DeviceUpdate != null)
				{
					uc_DeviceUpdate.DongleVersion = value;
				}
			}
		}

		public byte DongleType
		{
			get
			{
				return 0;
			}
			set
			{
				if (uc_DeviceUpdate != null)
				{
					uc_DeviceUpdate.DongleType = value;
				}
			}
		}

		public string MouseVersion
		{
			get
			{
				return "";
			}
			set
			{
				if (uc_DeviceUpdate != null)
				{
					uc_DeviceUpdate.MouseVersion = value;
				}
			}
		}

		public int PowerSaveTime
		{
			get
			{
				return powerSaveTime;
			}
			set
			{
				powerSaveTime = value;
				if (uc_Light != null)
				{
					uc_Light.Update_PowerSaveTime(value);
				}
			}
		}

		public event ExitPairingEventHandler ExitPairing;

		public event LanguageChangeEventHandler LanguageChange;

		public event DeviceUpdateFailEventHandler DeviceUpdateFail;

		public event UpdateFinishEventHandler UpdateFinish;

		public CustomSetting()
		{
			InitializeComponent();
		}

		public void UpdateUI(LanguageFile language, DriveConfig.DeviceParam deviceParam)
		{
			languageFile = language;
			int num = 0;
			lockControlCount = base.Controls.Count;
			SetLabel(languageFile.LanguageIndex);
			uc_Language = new UC_Language(languageFile);
			uc_Language.Location = new Point(0, num);
			uc_Language.LanguageChange += Language_LanguageChange;
			panel1.Controls.Add(uc_Language);
			num = uc_Language.Bottom;
			uc_DeviceUpdate = new UC_DeviceUpdate(language, deviceParam);
			uc_DeviceUpdate.Location = new Point(0, num);
			uc_DeviceUpdate.DeviceUpdating += DeviceUpdate_DeviceUpdating;
			uc_DeviceUpdate.DeviceUpdateFail += DeviceUpdate_DeviceUpdateFail;
			panel1.Controls.Add(uc_DeviceUpdate);
			num = uc_DeviceUpdate.Bottom;
			uc_Pair = new UC_Pair();
			uc_Pair.Location = new Point(0, num);
			uc_Pair.ExitPairing += Uc_Pair_ExitPairing;
			panel1.Controls.Add(uc_Pair);
			num = uc_Pair.Bottom;
			if (!FormMain.deviceParam.DisplayLight)
			{
				uc_Light = new UC_Light();
				uc_Light.Location = new Point(0, num);
				panel1.Controls.Add(uc_Light);
				num = uc_Light.Bottom;
			}
			uc_System = new UC_System();
			uc_System.Location = new Point(0, num);
			panel1.Controls.Add(uc_System);
			num = uc_System.Bottom;
			uc_Web = new UC_Web(language);
			uc_Web.Location = new Point(0, num);
			panel1.Controls.Add(uc_Web);
			ResourcesFile.SetControlBitmap(this);
			AdjustWebLocation(num);
			if (uc_Light != null)
			{
				uc_Light.UI_Init();
			}
		}

		private void Uc_Pair_ExitPairing(object sender)
		{
			ExitPair();
		}

		private void DeviceUpdate_DeviceUpdateFail(object sender)
		{
			DeviceUpdateFail?.Invoke(this);
		}

		public void EnterPair()
		{
			if (uc_Pair != null)
			{
				pairing = true;
				uc_Pair.EnterPair();
			}
		}

		public void ExitPair()
		{
			if (uc_Pair != null && pairing)
			{
				pairing = false;
				uc_Pair.ExitPair();
			}
			ExitPairing?.Invoke(this);
		}

		public void AddAdvanced()
		{
			int bottom = uc_System.Bottom;
			uc_Advanced = new UC_Advanced();
			uc_Advanced.Location = new Point(0, bottom);
			panel1.Controls.Add(uc_Advanced);
			bottom = uc_Advanced.Bottom;
			uc_Web.Location = new Point(0, bottom);
			AdjustWebLocation(bottom);
		}

		private void AdjustWebLocation(int y)
		{
			int num = y;
			uc_Web.Location = new Point(0, y);
			num = uc_Web.Bottom;
			ResourcesFile.SetControlBitmap(this);
			if (uc_Light != null)
			{
				uc_Light.UI_Init();
			}
			ControlsPoints.Clear();
			LockPointIndexs.Clear();
			for (int i = 0; i < panel1.Controls.Count; i++)
			{
				ControlsPoints.Add(panel1.Controls[i].Location);
				if (panel1.Controls[i].TabIndex < lockControlCount)
				{
					LockPointIndexs.Add(i);
					continue;
				}
				panel1.Controls[i].BackgroundImageLayout = ImageLayout.Stretch;
				panel1.Controls[i].BackgroundImage = new Bitmap(AppDomain.CurrentDomain.BaseDirectory + "\\res\\7General\\split.png");
			}
			panel1.Height = num + 3;
			int num2 = customScrollBar1.Size.Height;
			if (num2 >= num)
			{
				customScrollBar1.Visible = false;
				panel1.Height = num2;
				return;
			}
			customScrollBar1.Visible = true;
			customScrollBar1.DocSize = panel1.Height;
			customScrollBar1.PageSize = num2;
			customScrollBar1.ScrollInterval = SystemInformation.MouseWheelScrollLines * 15;
			customScrollBar1.DocPosition = 0f;
		}

		public void SetDongleRGB(byte[] rgb)
		{
			if (uc_Advanced != null)
			{
				uc_Advanced.UpdateDongleLED(rgb[0]);
			}
		}

		public byte[] GetDongleRGB()
		{
			return new byte[10];
		}

		public void AddDongleRGB()
		{
			if (uc_Advanced == null)
			{
				AddAdvanced();
			}
			if (!addDongleRGB)
			{
				addDongleRGB = true;
				uc_Advanced.AddDongleLED();
				AdjustWebLocation(uc_Advanced.Bottom);
			}
		}

		public void AddLongDistance()
		{
			if (uc_Advanced == null)
			{
				AddAdvanced();
			}
			if (!addLongDistance)
			{
				addLongDistance = true;
				uc_Advanced.AddLongDistance();
				AdjustWebLocation(uc_Advanced.Bottom);
			}
		}

		public void RemoteAdvanced()
		{
			if (uc_Advanced != null)
			{
				int bottom = uc_System.Bottom;
				panel1.Controls.Remove(uc_Advanced);
				uc_Advanced = null;
				uc_Web.Location = new Point(0, bottom);
				AdjustWebLocation(bottom);
			}
		}

		private void Language_LanguageChange(object sender, CustomEventArgs e)
		{
			SetLabel((int)e.Value);
			LanguageChange?.Invoke(this, e);
			if (uc_DeviceUpdate != null)
			{
				uc_DeviceUpdate.LanguageChange();
			}
			if (uc_Pair != null)
			{
				uc_Pair.LanguageChange();
			}
			if (uc_System != null)
			{
				uc_System.LanguageChange();
			}
			if (uc_Advanced != null)
			{
				uc_Advanced.LanguageChange();
			}
			if (uc_Web != null)
			{
				uc_Web.LanguageChange();
			}
			if (uc_Light != null)
			{
				uc_Light.LanguageChange();
			}
		}

		private void SetLabel(int index)
		{
			label_DriveVersionValue.Text = FormMain.driveParam.Version;
			label_DriveVersionValue.Location = new Point(panel1.Width - label_DriveVersionValue.Width, label_DriveVersionValue.Top);
			label_DriveVersion.Text = languageFile.FromSettingString[0];
			label_DriveVersion.Location = new Point(label_DriveVersionValue.Left - label_DriveVersion.Width, label_DriveVersion.Top);
		}

		private void DeviceUpdate_DeviceUpdating(object sender, bool updating)
		{
			this.updating = updating;
			if (!updating)
			{
				UpdateFinish?.Invoke(this);
			}
		}

		public void RestDongleButton()
		{
			if (uc_DeviceUpdate != null)
			{
				uc_DeviceUpdate.ResetDongleButton();
			}
		}

		protected override void OnMouseWheel(MouseEventArgs e)
		{
			base.OnMouseWheel(e);
			if (customScrollBar1.Visible)
			{
				bool num = e.Delta <= 0;
				float docPosition = customScrollBar1.DocPosition;
				docPosition = (num ? ((docPosition + customScrollBar1.ScrollInterval > customScrollBar1.DocSize - customScrollBar1.PageSize) ? (customScrollBar1.DocSize - customScrollBar1.PageSize) : (docPosition + customScrollBar1.ScrollInterval)) : ((docPosition - customScrollBar1.ScrollInterval < 0f) ? 0f : (docPosition - customScrollBar1.ScrollInterval)));
				customScrollBar1.DocPosition = docPosition;
				customScrollBar1_CustomScroll(null, null);
			}
		}

		private void customScrollBar1_CustomScroll(object sender, CustomEventArgs e)
		{
			bool flag = false;
			for (int i = 0; i < panel1.Controls.Count; i++)
			{
				flag = false;
				for (int j = 0; j < LockPointIndexs.Count; j++)
				{
					if (i == LockPointIndexs[j])
					{
						flag = true;
						break;
					}
				}
				if (!flag)
				{
					panel1.Controls[i].Location = new Point(ControlsPoints[i].X, ControlsPoints[i].Y - Convert.ToInt32(customScrollBar1.DocPosition));
				}
			}
		}

		protected override void Dispose(bool disposing)
		{
			if (disposing && components != null)
			{
				components.Dispose();
			}
			base.Dispose(disposing);
		}

